(window.__X=window.__X||{})["rc01"]={"schema_version":1,"source":"정기시험 기출문제집 4 1000 RC","test":1,"parts":{"5":[{"n":101,"sentence":"Former Sendai Company CEO Ken Nakata spoke about _____ career experiences.","sentence_th":"Ken Nakata อดีต CEO ของบริษัท Sendai ได้พูดถึงประสบการณ์ในอาชีพการงานของเขา","options":{"A":"he","B":"his","C":"him","D":"himself"},"options_th":{"A":"เขา (ประธาน)","B":"ของเขา (แสดงความเป็นเจ้าของ)","C":"เขา (กรรม)","D":"ตัวเขาเอง (สรรพนามสะท้อน)"},"answer":"B","category":"Personal pronoun case – possessive","category_th":"การกของสรรพนามบุรุษ – รูปแสดงความเป็นเจ้าของ","explain_th":"ช่องว่างอยู่หน้าคำนามประสม career experiences จึงต้องใช้สรรพนามที่ทำหน้าที่ขยายคำนามได้ คือรูปแสดงความเป็นเจ้าของ (B) his","vocab":[["former","อดีต, ก่อนหน้านี้"]],"part":5},{"n":102,"sentence":"Passengers who will be taking a _____ domestic flight should go to Terminal A.","sentence_th":"ผู้โดยสารที่จะต่อเที่ยวบินภายในประเทศ (เที่ยวบินต่อเครื่อง) ควรไปที่อาคารผู้โดยสาร A","options":{"A":"connectivity","B":"connects","C":"connect","D":"connecting"},"options_th":{"A":"การเชื่อมต่อ (n.)","B":"เชื่อมต่อ (v. เอกพจน์)","C":"เชื่อมต่อ (v.)","D":"ที่เชื่อมต่อ (v-ing ทำหน้าที่ adj.)"},"answer":"D","category":"Adjective position – modifying a noun / present participle","category_th":"ตำแหน่งคำคุณศัพท์ – ขยายคำนาม / present participle","explain_th":"หน้าช่องว่างมี a หลังช่องว่างเป็นโครงสร้าง adj.+noun คือ domestic flight จึงต้องใช้คำที่ทำหน้าที่ adj. ขยาย flight ความหมาย 'เที่ยวบินภายในประเทศที่ต่อเครื่อง' → present participle (D) connecting  (A) เป็นคำนาม (B)(C) เป็นกริยา ใส่ไม่ได้","vocab":[["passenger","ผู้โดยสาร"],["domestic","ภายในประเทศ"],["connectivity","การเชื่อมต่อ"]],"part":5},{"n":103,"sentence":"Fresh and _____ apple-cider donuts are available at Oakcrest Orchard’s retail shop for £6 per dozen.","sentence_th":"โดนัทแอปเปิลไซเดอร์ที่สดใหม่และอร่อยมีจำหน่ายที่ร้านขายปลีกของสวนผลไม้ Oakcrest ในราคาโหลละ 6 ปอนด์","options":{"A":"eaten","B":"open","C":"tasty","D":"free"},"options_th":{"A":"ที่ถูกกินแล้ว","B":"เปิด, ที่เปิดอยู่","C":"อร่อย","D":"ฟรี; อิสระ"},"answer":"C","category":"Adjective vocabulary","category_th":"คำศัพท์ – คำคุณศัพท์","explain_th":"ช่องว่างขยายคำนามประสม apple-cider donuts คู่กับ Fresh ความหมาย 'โดนัทที่สดและอร่อย' จึงเหมาะสม → (C) tasty  (A) eaten = ที่ถูกกินแล้ว (B) open = เปิด (D) free = ฟรี/อิสระ ไม่เข้าความหมาย","vocab":[["orchard","สวนผลไม้"],["retail","ขายปลีก"],["per","ต่อ"],["dozen","โหล (12 ชิ้น)"]],"part":5},{"n":104,"sentence":"Zahn Flooring has the widest selection of _____ in the United Kingdom.","sentence_th":"Zahn Flooring มีกระเบื้องให้เลือกหลากหลายที่สุดในสหราชอาณาจักร","options":{"A":"paints","B":"tiles","C":"furniture","D":"curtains"},"options_th":{"A":"สี (ทาบ้าน)","B":"กระเบื้อง","C":"เฟอร์นิเจอร์","D":"ผ้าม่าน"},"answer":"B","category":"Noun vocabulary","category_th":"คำศัพท์ – คำนาม","explain_th":"ต้องเลือกสินค้าที่ Zahn Flooring มีจำหน่าย ชื่อบริษัทมีคำว่า Flooring (วัสดุปูพื้น) จึงเป็นร้านขายวัสดุปูพื้น สินค้าที่หลากหลายที่สุดควรเป็น 'กระเบื้อง' → (B) tiles  ส่วน paint สี, furniture เฟอร์นิเจอร์, curtain ผ้าม่าน ไม่ใช่สินค้าหลักของร้านวัสดุปูพื้น","vocab":[["a selection of","ตัวเลือกที่หลากหลาย"]],"part":5},{"n":105,"sentence":"One responsibility of the IT department is to ensure that the company is using _____ software.","sentence_th":"หนึ่งในหน้าที่ของแผนก IT คือการทำให้มั่นใจว่าบริษัทใช้ซอฟต์แวร์ที่อัปเดตแล้ว","options":{"A":"update","B":"updating","C":"updates","D":"updated"},"options_th":{"A":"อัปเดต (v./n.)","B":"ที่กำลังอัปเดต (v-ing)","C":"อัปเดต (v. เอกพจน์ / n. พหูพจน์)","D":"ที่ได้รับการอัปเดตแล้ว (v-ed)"},"answer":"D","category":"Adjective position – present vs. past participle","category_th":"ตำแหน่งคำคุณศัพท์ – present participle vs. past participle","explain_th":"ช่องว่างขยายคำนาม software ความหมาย 'ซอฟต์แวร์ที่ถูกอัปเดตแล้ว' เป็นความหมายถูกกระทำ จึงใช้ past participle (D) updated  (A)(C) ถ้าเป็นคำนามก็ไม่เป็นคำนามประสมกับ software ได้เหมาะ (B) updating มีความหมายเชิงทำเอง แต่ software เป็นสิ่งที่ถูกอัปเดต","vocab":[["responsibility","หน้าที่, ความรับผิดชอบ"],["ensure","ทำให้มั่นใจ"]],"part":5},{"n":106,"sentence":"It is wise to check a company’s dress code _____ visiting its head office.","sentence_th":"ควรตรวจสอบระเบียบการแต่งกายของบริษัทก่อนไปเยี่ยมชมสำนักงานใหญ่","options":{"A":"so","B":"how","C":"like","D":"before"},"options_th":{"A":"ดังนั้น (คำเชื่อม)","B":"อย่างไร","C":"เหมือน (บุพบท)","D":"ก่อน (บุพบท/คำเชื่อม)"},"answer":"D","category":"Preposition position / vocabulary","category_th":"ตำแหน่งและความหมายของบุพบท","explain_th":"ช่องว่างเชื่อมประโยคหลัก It is wise to check … dress code กับ visiting its head office ความหมาย 'ก่อนไปเยี่ยมสำนักงานใหญ่' → (D) before  จำไว้ว่า before -ing (ก่อนทำ…) และ after -ing (หลังทำ…) ออกสอบบ่อย","vocab":[["wise","ฉลาด, สมควร"],["head office","สำนักงานใหญ่"]],"part":5},{"n":107,"sentence":"Wexler Store’s management team expects that employees will _____ support any new hires.","sentence_th":"ทีมผู้บริหารของ Wexler Store คาดหวังว่าพนักงานจะสนับสนุนพนักงานใหม่ทุกคนอย่างกระตือรือร้น","options":{"A":"enthusiastically","B":"enthusiasm","C":"enthusiastic","D":"enthused"},"options_th":{"A":"อย่างกระตือรือร้น (adv.)","B":"ความกระตือรือร้น (n.)","C":"กระตือรือร้น (adj.)","D":"ทำให้กระตือรือร้น (v. อดีต/p.p.)"},"answer":"A","category":"Adverb position – modifying a verb","category_th":"ตำแหน่งคำกริยาวิเศษณ์ – ขยายคำกริยา","explain_th":"ช่องว่างอยู่ระหว่างกริยาช่วย will กับกริยาแท้ support จึงเป็นตำแหน่ง adv. ขยายกริยา → (A) enthusiastically  (B) เป็นคำนาม (C) เป็น adj. (D) เป็นกริยา/past participle ใส่ไม่ได้","vocab":[["new hire","พนักงานใหม่"],["enthusiasm","ความกระตือรือร้น"]],"part":5},{"n":108,"sentence":"Wheel alignments and brake system _____ are part of our vehicle service plan.","sentence_th":"การตั้งศูนย์ล้อและการตรวจสอบระบบเบรกเป็นส่วนหนึ่งของแผนบริการรถยนต์ของเรา","options":{"A":"inspects","B":"inspector","C":"inspected","D":"inspections"},"options_th":{"A":"ตรวจสอบ (v. เอกพจน์)","B":"ผู้ตรวจสอบ (n. นับได้ เอกพจน์)","C":"ถูกตรวจสอบ (v-ed)","D":"การตรวจสอบ (n. พหูพจน์)"},"answer":"D","category":"Noun position – compound noun","category_th":"ตำแหน่งคำนาม – คำนามประสม","explain_th":"ช่องว่างเป็นประธานของกริยา are เชื่อมด้วย and ขนานกับคำนามประสม Wheel alignments จึงต้องเป็นคำนามที่รวมกับ brake system เป็นคำนามประสม ความหมาย 'การตรวจสอบระบบเบรก' → (D) inspections  (B) inspector (ผู้ตรวจ) เป็นนามนับได้เอกพจน์ ต้องมี a/the นำหน้า จึงผิด","vocab":[["wheel alignment","การตั้งศูนย์ล้อ"],["plan","แผน/โครงการ (บริการ, ประกัน)"],["inspect","ตรวจสอบ"]],"part":5},{"n":109,"sentence":"Registration for the Marketing Coalition Conference is now open _____ September 30.","sentence_th":"ขณะนี้เปิดลงทะเบียนสำหรับการประชุม Marketing Coalition Conference แล้ว จนถึงวันที่ 30 กันยายน","options":{"A":"until","B":"into","C":"yet","D":"while"},"options_th":{"A":"จนถึง (บุพบท)","B":"เข้าไปใน (บุพบท)","C":"ยัง; แต่ (adv./คำเชื่อม)","D":"ขณะที่ (คำเชื่อม)"},"answer":"A","category":"Preposition position / vocabulary","category_th":"ตำแหน่งและความหมายของบุพบท","explain_th":"ประโยคสมบูรณ์แล้ว (Registration … is open) และหลังช่องว่างเป็นคำนาม September 30 จึงต้องเป็นบุพบท ความหมาย 'ลงทะเบียนได้จนถึง 30 ก.ย.' → (A) until  (B) into เป็นบุพบทแต่แปลว่า 'เข้าไปใน' (C) yet เป็น adv./คำเชื่อม (D) while เป็นคำเชื่อม ใส่ไม่ได้","vocab":[["registration","การลงทะเบียน"],["coalition","กลุ่มพันธมิตร, สหพันธ์"]],"part":5},{"n":110,"sentence":"Growth in the home entertainment industry has been _____ this quarter.","sentence_th":"การเติบโตของอุตสาหกรรมความบันเทิงภายในบ้านค่อนข้างจำกัดในไตรมาสนี้","options":{"A":"separate","B":"limited","C":"willing","D":"assorted"},"options_th":{"A":"แยกกัน","B":"จำกัด, มีไม่มาก","C":"เต็มใจ","D":"หลากหลาย, คละกัน"},"answer":"B","category":"Adjective vocabulary","category_th":"คำศัพท์ – คำคุณศัพท์","explain_th":"หลัง has been ต้องเป็น adj. ทำหน้าที่ส่วนเติมเต็มอธิบายประธาน Growth ความหมาย 'การเติบโตจำกัด (ไม่มาก)' เหมาะสม → (B) limited  (A) แยกกัน (C) เต็มใจ (D) หลากหลาย ไม่เข้าความหมาย","vocab":[["quarter","ไตรมาส (1 ใน 4 ของปี)"]],"part":5},{"n":111,"sentence":"Hawson Furniture will be making _____ on the east side of town on Thursday.","sentence_th":"Hawson Furniture จะไปส่งของทางฝั่งตะวันออกของเมืองในวันพฤหัสบดี","options":{"A":"deliveries","B":"delivered","C":"deliver","D":"deliverable"},"options_th":{"A":"การจัดส่ง (n. พหูพจน์)","B":"ส่งแล้ว (v. อดีต/p.p.)","C":"ส่ง (v.)","D":"ที่ส่งได้ (adj.); สิ่งที่ต้องส่งมอบ (n.)"},"answer":"A","category":"Noun position – object of a verb","category_th":"ตำแหน่งคำนาม – กรรมของกริยา","explain_th":"ช่องว่างเป็นกรรมของ will be making ต้องเป็นคำนาม make deliveries = 'ส่งของ' → (A) deliveries  (B) เป็นกริยา/past participle (C) เป็นกริยา (D) deliverable ถ้าเป็นคำนามก็เป็นนามนับได้เอกพจน์ ต้องมีคำนำหน้า ใช้เดี่ยว ๆ ไม่ได้","vocab":[["deliverable","ที่ส่งได้; สิ่งที่ต้องส่งมอบ, สินค้า"]],"part":5},{"n":112,"sentence":"The Marlton City Council does not have the authority to _____ parking on city streets.","sentence_th":"สภาเมือง Marlton ไม่มีอำนาจที่จะห้ามจอดรถบนถนนในเมือง","options":{"A":"drive","B":"prohibit","C":"bother","D":"travel"},"options_th":{"A":"ขับรถ","B":"ห้าม","C":"รบกวน","D":"เดินทาง"},"answer":"B","category":"Verb vocabulary","category_th":"คำศัพท์ – คำกริยา","explain_th":"ช่องว่างเป็นกริยาใน to-infinitive ที่ขยาย authority มีกรรมคือ parking ความหมาย 'อำนาจในการห้ามจอดรถ' → (B) prohibit  (A) ขับ (C) รบกวน (D) เดินทาง ไม่เข้าความหมาย","vocab":[["authority","อำนาจ"]],"part":5},{"n":113,"sentence":"Project Earth Group is _____ for ways to reduce transport-related greenhouse gas emissions.","sentence_th":"Project Earth Group กำลังหาวิธีลดการปล่อยก๊าซเรือนกระจกที่เกี่ยวข้องกับการขนส่ง","options":{"A":"looking","B":"seeing","C":"driving","D":"leaning"},"options_th":{"A":"มองหา (look for)","B":"เห็น","C":"ขับ","D":"เอนพิง"},"answer":"A","category":"Verb vocabulary","category_th":"คำศัพท์ – คำกริยา","explain_th":"หลังช่องว่างไม่มีกรรมแต่มีบุพบท for จึงต้องเป็นกริยาไม่ต้องการกรรมที่ใช้คู่ for ได้ look for = 'มองหา' ได้ความ 'กำลังหาวิธี' → (A) looking","vocab":[["reduce","ลด"],["transport","การขนส่ง"],["related","ที่เกี่ยวข้อง"],["greenhouse gas","ก๊าซเรือนกระจก"],["emission","การปล่อย (ก๊าซ)"]],"part":5},{"n":114,"sentence":"Our skilled tailors are happy to design a custom-made suit that fits your style and budget _____.","sentence_th":"ช่างตัดเสื้อผู้ชำนาญของเรายินดีออกแบบสูทสั่งตัดที่เข้ากับสไตล์และงบประมาณของคุณได้อย่างลงตัว","options":{"A":"perfect","B":"perfects","C":"perfectly","D":"perfection"},"options_th":{"A":"สมบูรณ์แบบ (adj.) / ทำให้สมบูรณ์ (v.)","B":"ทำให้สมบูรณ์ (v. เอกพจน์)","C":"อย่างสมบูรณ์แบบ (adv.)","D":"ความสมบูรณ์แบบ (n.)"},"answer":"C","category":"Adverb position – modifying a verb","category_th":"ตำแหน่งคำกริยาวิเศษณ์ – ขยายคำกริยา","explain_th":"ช่องว่างอยู่ใน relative clause ที่ขยาย a custom-made suit และขยายกริยา fits จึงเป็นตำแหน่ง adv. → (C) perfectly  (A) adj./กริยา (B) กริยา (D) คำนาม ใส่ไม่ได้","vocab":[["skilled","ชำนาญ"],["tailor","ช่างตัดเสื้อ"],["custom-made","สั่งตัด"],["suit","ชุดสูท"],["fit","พอดี, เข้ากับ"],["budget","งบประมาณ"]],"part":5},{"n":115,"sentence":"Project manager Hannah Chung has proved to be very _____ with completing company projects.","sentence_th":"ผู้จัดการโครงการ Hannah Chung พิสูจน์แล้วว่าช่วยได้มากในการทำโครงการของบริษัทให้สำเร็จ","options":{"A":"helpfulness","B":"help","C":"helpfully","D":"helpful"},"options_th":{"A":"ความเป็นประโยชน์ (n.)","B":"ช่วย (v.) / ความช่วยเหลือ (n.)","C":"อย่างเป็นประโยชน์ (adv.)","D":"เป็นประโยชน์, ช่วยได้ (adj.)"},"answer":"D","category":"Adjective position – complement","category_th":"ตำแหน่งคำคุณศัพท์ – ส่วนเติมเต็ม","explain_th":"หลัง proved to be กริยา be ต้องการส่วนเติมเต็ม และมี very ขยายอยู่ข้างหน้า จึงต้องเป็น adj. → (D) helpful  (A) คำนาม (B) กริยา/คำนาม (C) adv. ใส่ไม่ได้","vocab":[["prove","พิสูจน์ได้ว่า, ปรากฏว่า"]],"part":5},{"n":116,"sentence":"Lehua Vacation Club members will receive double points _____ the month of August at participating hotels.","sentence_th":"สมาชิก Lehua Vacation Club จะได้รับคะแนนสะสมสองเท่าตลอดเดือนสิงหาคมที่โรงแรมที่ร่วมรายการ","options":{"A":"onto","B":"above","C":"during","D":"between"},"options_th":{"A":"ขึ้นไปบน","B":"เหนือ, มากกว่า","C":"ระหว่าง (ช่วงเวลา), ตลอด","D":"ระหว่าง (A และ B)"},"answer":"C","category":"Preposition vocabulary","category_th":"คำศัพท์ – บุพบท","explain_th":"หลังช่องว่างเป็นนามวลีบอกช่วงเวลา the month of August ความหมาย 'ตลอดช่วงเดือนสิงหาคม' → (C) during  (A) onto = ขึ้นไปบน (B) above = เหนือ (D) between ใช้รูป between A and B หมายถึงระหว่างสองจุด","vocab":[["participating","ที่เข้าร่วม"]],"part":5},{"n":117,"sentence":"The costumes were not received _____ enough to be used in the first dress rehearsal.","sentence_th":"ได้รับชุดการแสดงไม่ทันพอที่จะใช้ในการซ้อมใหญ่ครั้งแรก","options":{"A":"far","B":"very","C":"almost","D":"soon"},"options_th":{"A":"ไกล","B":"มาก","C":"เกือบ","D":"เร็ว, ในไม่ช้า"},"answer":"D","category":"Adverb vocabulary","category_th":"คำศัพท์ – คำกริยาวิเศษณ์","explain_th":"ช่องว่างขยายกริยา were not received และอยู่ในโครงสร้าง 'adv. + enough + to-infinitive' (…พอที่จะ…) ความหมาย 'ไม่ได้รับเร็วพอที่จะใช้ในการซ้อมใหญ่ครั้งแรก' → (D) soon  (A) ไกล (B) มาก (C) เกือบ ไม่เข้าความหมาย","vocab":[["costume","ชุดการแสดง"],["dress rehearsal","การซ้อมใหญ่ (สวมชุดจริงเหมือนแสดงจริง)"]],"part":5},{"n":118,"sentence":"As a former publicist for several renowned orchestras, Mr. Wu would excel in the role of event _____.","sentence_th":"ในฐานะอดีตเจ้าหน้าที่ประชาสัมพันธ์ของวงออร์เคสตราชื่อดังหลายวง คุณ Wu น่าจะทำได้ดีเยี่ยมในบทบาทผู้จัดงานอีเวนต์","options":{"A":"organized","B":"organizer","C":"organizes","D":"organizational"},"options_th":{"A":"จัดแล้ว (v. อดีต/p.p.)","B":"ผู้จัด (n.)","C":"จัด (v. เอกพจน์)","D":"เกี่ยวกับองค์กร/การจัดการ (adj.)"},"answer":"B","category":"Noun position – compound noun","category_th":"ตำแหน่งคำนาม – คำนามประสม","explain_th":"ช่องว่างรวมกับคำนาม event เป็นคำนามประสมที่เป็นกรรมของบุพบท of ความหมาย 'ผู้จัดงาน' → (B) organizer  (A) กริยา/past participle (C) กริยา (D) adj. ใส่ไม่ได้","vocab":[["former","อดีต"],["publicist","เจ้าหน้าที่ประชาสัมพันธ์"],["renowned","มีชื่อเสียง"],["excel","ทำได้ดีเยี่ยม"]],"part":5},{"n":119,"sentence":"The northbound lane on Davis Street will be _____ closed because of the city’s bridge reinforcement project.","sentence_th":"ช่องทางมุ่งหน้าทิศเหนือบนถนน Davis จะถูกปิดชั่วคราวเนื่องจากโครงการเสริมความแข็งแรงสะพานของเมือง","options":{"A":"temporarily","B":"competitively","C":"recently","D":"collectively"},"options_th":{"A":"ชั่วคราว","B":"อย่างมีการแข่งขัน","C":"เมื่อเร็ว ๆ นี้","D":"โดยรวม, ร่วมกัน"},"answer":"A","category":"Adverb vocabulary","category_th":"คำศัพท์ – คำกริยาวิเศษณ์","explain_th":"ต้องเลือก adv. ขยาย will be closed ความหมาย 'ช่องทางจะปิดชั่วคราวเพราะงานก่อสร้าง' → (A) temporarily  (B) อย่างแข่งขัน (D) โดยรวม ไม่เข้าความหมาย (C) recently มักใช้กับ present perfect หรืออดีต ไม่ใช้กับอนาคต","vocab":[["northbound","มุ่งหน้าทิศเหนือ"],["lane","ช่องทางเดินรถ"],["reinforcement","การเสริมความแข็งแรง"]],"part":5},{"n":120,"sentence":"Airline representatives must handle a wide range of passenger issues, _____ missed connections to lost luggage.","sentence_th":"พนักงานสายการบินต้องจัดการปัญหาของผู้โดยสารหลากหลายรูปแบบ ตั้งแต่การตกเที่ยวบินต่อเครื่องไปจนถึงกระเป๋าเดินทางสูญหาย","options":{"A":"from","B":"under","C":"on","D":"against"},"options_th":{"A":"จาก, ตั้งแต่","B":"ใต้","C":"บน; เกี่ยวกับ","D":"ต่อต้าน; พิง"},"answer":"A","category":"Preposition vocabulary","category_th":"คำศัพท์ – บุพบท","explain_th":"หลังช่องว่างมี to lost luggage จึงเข้ารูป from A to B 'ตั้งแต่การตกเที่ยวบินต่อเครื่องไปจนถึงกระเป๋าหาย' → (A) from","vocab":[["representative","พนักงาน, ตัวแทน"],["handle","จัดการ"],["a range of","หลากหลาย"],["passenger","ผู้โดยสาร"],["issue","ปัญหา"],["connection","เที่ยวบินต่อ (การเดินทาง)"],["luggage","กระเป๋าเดินทาง, สัมภาระ"]],"part":5},{"n":121,"sentence":"The meeting notes were _____ deleted, but Mr. Hahm was able to recreate them from memory.","sentence_th":"บันทึกการประชุมถูกลบโดยไม่ได้ตั้งใจ แต่คุณ Hahm สามารถเขียนขึ้นใหม่ได้จากความจำ","options":{"A":"accident","B":"accidental","C":"accidents","D":"accidentally"},"options_th":{"A":"อุบัติเหตุ (n.)","B":"โดยบังเอิญ (adj.)","C":"อุบัติเหตุ (n. พหูพจน์)","D":"โดยไม่ได้ตั้งใจ, โดยบังเอิญ (adv.)"},"answer":"D","category":"Adverb position – modifying a verb","category_th":"ตำแหน่งคำกริยาวิเศษณ์ – ขยายคำกริยา","explain_th":"ช่องว่างขยายกริยา were deleted จึงเป็นตำแหน่ง adv. → (D) accidentally (โดยไม่ได้ตั้งใจ)  (A)(C) คำนาม (B) adj. ใส่ไม่ได้","vocab":[["delete","ลบ"],["recreate","สร้างขึ้นใหม่"],["memory","ความจำ"]],"part":5},{"n":122,"sentence":"The current issue of Farming Scene magazine predicts that the price of corn will rise 5 percent over the _____ year.","sentence_th":"นิตยสาร Farming Scene ฉบับล่าสุดคาดการณ์ว่าราคาข้าวโพดจะสูงขึ้น 5 เปอร์เซ็นต์ในปีหน้า","options":{"A":"next","B":"with","C":"which","D":"now"},"options_th":{"A":"ถัดไป (adj.)","B":"กับ (บุพบท)","C":"ซึ่ง (relative pronoun)","D":"ตอนนี้ (adv.)"},"answer":"A","category":"Adjective position – modifying a noun","category_th":"ตำแหน่งคำคุณศัพท์ – ขยายคำนาม","explain_th":"มี the อยู่หน้า และคำนาม year อยู่หลัง ช่องว่างจึงเป็น adj. ขยาย year → (A) next  (B) บุพบท (C) relative/question pronoun (D) adv. ใส่ไม่ได้","vocab":[["issue","ฉบับ (ของนิตยสาร)"],["predict","คาดการณ์"],["rise","สูงขึ้น"]],"part":5},{"n":123,"sentence":"Anyone who still _____ to take the fire safety training should do so before the end of the month.","sentence_th":"ใครก็ตามที่ยังต้องเข้ารับการอบรมความปลอดภัยด้านอัคคีภัยควรเข้ารับก่อนสิ้นเดือนนี้","options":{"A":"needing","B":"needs","C":"has needed","D":"were needing"},"options_th":{"A":"ต้องการ (v-ing)","B":"ต้อง (present เอกพจน์)","C":"ต้องแล้ว (present perfect)","D":"กำลังต้อง (past continuous พหูพจน์)"},"answer":"B","category":"Verb position – agreement + tense","category_th":"ตำแหน่งคำกริยา – การผันตามประธาน + กาล","explain_th":"ช่องว่างเป็นกริยาใน relative clause (who still … safety training) ที่ขยาย Anyone กริยาต้องผันตามคำที่ขยาย Anyone เป็นเอกพจน์ และเป็นการบอกเงื่อนไขของผู้ที่ต้องทำหน้าที่ จึงใช้ present tense → (B) needs  (A) v-ing เป็นกริยาแท้ไม่ได้ (C) กาลไม่เหมาะ (D) ไม่สอดคล้องกับ Anyone","vocab":[],"part":5},{"n":124,"sentence":"Emerging technologies have _____ begun to transform the shipping industry in ways that were once unimaginable.","sentence_th":"เทคโนโลยีเกิดใหม่ได้เริ่มเปลี่ยนแปลงอุตสาหกรรมการขนส่งในแบบที่ครั้งหนึ่งเคยนึกไม่ถึงแล้ว","options":{"A":"already","B":"exactly","C":"hardly","D":"closely"},"options_th":{"A":"แล้ว, เรียบร้อยแล้ว","B":"อย่างแน่นอน, ตรง","C":"แทบจะไม่","D":"อย่างใกล้ชิด"},"answer":"A","category":"Adverb vocabulary","category_th":"คำศัพท์ – คำกริยาวิเศษณ์","explain_th":"ต้องเลือก adv. ขยาย have begun ความหมาย 'เทคโนโลยีใหม่ได้เริ่มเปลี่ยนอุตสาหกรรมแล้ว' → (A) already  (B) อย่างแม่นยำ (C) แทบจะไม่ (D) อย่างใกล้ชิด ไม่เข้าความหมาย","vocab":[["emerging","ที่เกิดขึ้นใหม่"],["transform","เปลี่ยนแปลงอย่างสิ้นเชิง"],["unimaginable","เกินจินตนาการ, นึกไม่ถึง"]],"part":5},{"n":125,"sentence":"The company handbook outlines the high _____ that employees are expected to meet every day.","sentence_th":"คู่มือบริษัทระบุมาตรฐานสูงที่พนักงานต้องทำให้ได้ในทุก ๆ วัน","options":{"A":"experts","B":"accounts","C":"recommendations","D":"standards"},"options_th":{"A":"ผู้เชี่ยวชาญ","B":"บัญชี; คำบอกเล่า","C":"คำแนะนำ","D":"มาตรฐาน"},"answer":"D","category":"Noun vocabulary","category_th":"คำศัพท์ – คำนาม","explain_th":"ต้องเลือกคำนามที่ถูกขยายด้วย high และ relative clause (that employees … meet every day) ความหมาย 'มาตรฐานสูงที่พนักงานต้องทำให้ได้' → (D) standards  (A) ผู้เชี่ยวชาญ (B) บัญชี (C) คำแนะนำ ไม่เข้าความหมาย","vocab":[["outline","สรุปให้เห็นภาพรวม, ระบุ"],["expect","คาดหวัง"],["meet","ทำได้ตาม (มาตรฐาน/เป้าหมาย)"]],"part":5},{"n":126,"sentence":"Because _____ of the board members have scheduling conflicts, the board meeting will be moved to a date when all can attend.","sentence_th":"เนื่องจากกรรมการบางคนมีตารางเวลาชนกัน การประชุมคณะกรรมการจึงจะถูกเลื่อนไปเป็นวันที่ทุกคนเข้าร่วมได้","options":{"A":"any","B":"everybody","C":"those","D":"some"},"options_th":{"A":"ใด ๆ, ใครก็ได้","B":"ทุกคน (เอกพจน์)","C":"เหล่านั้น","D":"บางส่วน, บางคน"},"answer":"D","category":"Indefinite pronoun","category_th":"สรรพนามไม่ชี้เฉพาะ","explain_th":"ช่องว่างเป็นประธานพหูพจน์ของกริยา have ในอนุประโยค because ความหมาย 'กรรมการบางคนมีตารางชน' → (D) some  (A) any ในประโยคบอกเล่าแปลว่า 'ใครก็ได้' ไม่เข้าความหมาย (B) everybody เป็นเอกพจน์ (C) those ใช้แทนคำนามพหูพจน์ที่กล่าวไปแล้ว ไม่เหมาะ","vocab":[["board","คณะกรรมการ"],["scheduling conflict","ตารางเวลาชนกัน"]],"part":5},{"n":127,"sentence":"The project _____ the collaboration of several teams across the company.","sentence_th":"โครงการนี้ต้องอาศัยความร่วมมือของหลายทีมทั่วทั้งบริษัท","options":{"A":"passed","B":"decided","C":"required","D":"performed"},"options_th":{"A":"ผ่าน","B":"ตัดสินใจ","C":"ต้องการ, ต้องอาศัย","D":"แสดง, ปฏิบัติ"},"answer":"C","category":"Verb vocabulary","category_th":"คำศัพท์ – คำกริยา","explain_th":"ช่องว่างเป็นกริยาของประธาน The project ความหมาย 'โครงการต้องอาศัยความร่วมมือ' → (C) required  (A) ผ่าน (B) ตัดสินใจ (D) ปฏิบัติ ไม่เข้าความหมาย","vocab":[["collaboration","ความร่วมมือ"]],"part":5},{"n":128,"sentence":"We cannot send the store’s coupon booklet to the printers until it _____ by Ms. Jeon.","sentence_th":"เราไม่สามารถส่งสมุดคูปองของร้านไปโรงพิมพ์ได้จนกว่าคุณ Jeon จะอนุมัติ","options":{"A":"is approving","B":"approves","C":"has been approved","D":"will be approved"},"options_th":{"A":"กำลังอนุมัติ (active)","B":"อนุมัติ (active)","C":"ได้รับการอนุมัติแล้ว (passive, present perfect)","D":"จะได้รับการอนุมัติ (passive, future)"},"answer":"C","category":"Verb form – voice + tense","category_th":"รูปกริยา – voice + กาล","explain_th":"ช่องว่างเป็นกริยาในอนุประโยค until หลังช่องว่างไม่มีกรรม มีแต่ by Ms. Jeon จึงต้องเป็น passive ตัด (A)(B) ซึ่งเป็น active และใน adverb clause บอกเวลา (until) ใช้ present หรือ present perfect แทนอนาคต จึงใช้ will ไม่ได้ ตัด (D) → (C) has been approved","vocab":[["booklet","สมุดเล่มเล็ก"]],"part":5},{"n":129,"sentence":"_____ the closure of Verdigold Transport Services, we are looking for a new shipping company.","sentence_th":"เนื่องจากบริษัท Verdigold Transport Services ปิดกิจการ เราจึงกำลังหาบริษัทขนส่งรายใหม่","options":{"A":"In spite of","B":"Just as","C":"In light of","D":"According to"},"options_th":{"A":"แม้ว่า, ทั้ง ๆ ที่","B":"เหมือนกับที่, ขณะที่","C":"เนื่องจาก, เมื่อพิจารณาถึง","D":"ตามที่ (ระบุ)"},"answer":"C","category":"Phrasal preposition vocabulary","category_th":"คำศัพท์ – บุพบทวลี","explain_th":"ความหมาย 'เมื่อพิจารณาจากการปิดกิจการของบริษัทขนส่งเดิม เราจึงหาบริษัทใหม่' → (C) In light of  (A) แม้ว่า (B) เหมือนกับ (D) ตามที่ ไม่เข้าความหมาย","vocab":[["closure","การปิดกิจการ"],["transport","การขนส่ง"]],"part":5},{"n":130,"sentence":"The _____ information provided by Uniss Bank’s brochure helps applicants understand the terms of their loans.","sentence_th":"ข้อมูลเพิ่มเติมในโบรชัวร์ของธนาคาร Uniss ช่วยให้ผู้สมัครเข้าใจเงื่อนไขเงินกู้ของตน","options":{"A":"arbitrary","B":"supplemental","C":"superfluous","D":"potential"},"options_th":{"A":"ตามอำเภอใจ","B":"เพิ่มเติม, เสริม","C":"เกินความจำเป็น","D":"ที่อาจเป็นไปได้"},"answer":"B","category":"Adjective vocabulary","category_th":"คำศัพท์ – คำคุณศัพท์","explain_th":"ต้องเลือก adj. บอกลักษณะของข้อมูลในโบรชัวร์ ซึ่งช่วยให้ผู้สมัครเข้าใจเงื่อนไขเงินกู้ (helps applicants understand the terms of their loans) จึงควรเป็น 'ข้อมูลเพิ่มเติม/เสริม' → (B) supplemental  (A) ตามอำเภอใจ (C) ไม่จำเป็น (D) ที่อาจเป็นไปได้ ไม่เข้าความหมาย","vocab":[["applicant","ผู้สมัคร"],["terms","เงื่อนไข"],["loan","เงินกู้"]],"part":5}],"6":[{"set":"131-134","part":6,"type":"announcement","passages":[{"label":"announcement","text":"Come to the Maxley Heights Center for Horticulture and learn how to create a beautiful, eco-friendly garden for your home or business. [131]. We will teach you how to plant a rain garden, which is simply a shallow sunken garden [132] a special soil mix to filter pollutants from rainwater flowing from nearby roads and rooftops. These gardens can be landscaped with native plants and flowers. [133], rain gardens are always beneficial to the local environment. Among other things, [134] improve drainage and protect rivers and streams.\n\nTo register, visit www.maxley-horticulture.org.","text_th":"มาที่ Maxley Heights Center for Horticulture แล้วเรียนรู้วิธีสร้างสวนที่สวยงามและเป็นมิตรต่อสิ่งแวดล้อมสำหรับบ้านหรือธุรกิจของคุณ [131] เราจะสอนวิธีปลูกสวนรับน้ำฝน (rain garden) ซึ่งก็คือสวนแบบหลุมตื้นที่ [132] ดินผสมสูตรพิเศษเพื่อกรองสารมลพิษออกจากน้ำฝนที่ไหลมาจากถนนและหลังคาบริเวณใกล้เคียง สวนเหล่านี้สามารถจัดภูมิทัศน์ด้วยพืชและดอกไม้พื้นเมืองได้ [133] สวนรับน้ำฝนให้ประโยชน์ต่อสิ่งแวดล้อมในท้องถิ่นเสมอ นอกจากนี้ [134] ยังช่วยให้การระบายน้ำดีขึ้นและปกป้องแม่น้ำลำธารด้วย\n\nลงทะเบียนได้ที่ www.maxley-horticulture.org"}],"vocab":[["horticulture","การทำสวน, พืชสวน"],["eco-friendly","เป็นมิตรต่อสิ่งแวดล้อม"],["shallow","ตื้น"],["sunken garden","สวนที่ต่ำกว่าระดับพื้นรอบข้าง"],["soil","ดิน"],["filter","กรอง"],["pollutant","สารมลพิษ"],["landscape","จัดภูมิทัศน์"],["native","พื้นเมือง, ท้องถิ่น"],["beneficial","เป็นประโยชน์"],["drainage","การระบายน้ำ"],["stream","ลำธาร"],["register","ลงทะเบียน"],["exhibit","นิทรรศการ, สิ่งที่จัดแสดง"],["rainfall","ปริมาณน้ำฝน"],["patio","ลานนอกบ้าน"],["easy-to-acquire","หาได้ง่าย"],["material","วัสดุ"],["host","เป็นเจ้าภาพ, จัด"]],"questions":[{"n":131,"options":{"A":"Children of all ages will enjoy the new exhibits.","B":"Learn about rainfall patterns across the region.","C":"Build a set of simple patio furniture with easy-to-acquire materials.","D":"Next Saturday at 4 P.M., we are hosting a free workshop for the public."},"options_th":{"A":"เด็กทุกวัยจะสนุกกับนิทรรศการใหม่","B":"เรียนรู้เกี่ยวกับรูปแบบปริมาณน้ำฝนทั่วภูมิภาค","C":"สร้างชุดเฟอร์นิเจอร์ลานบ้านแบบง่าย ๆ ด้วยวัสดุที่หาได้ง่าย","D":"วันเสาร์หน้าเวลา 4 โมงเย็น เราจะจัดเวิร์กช็อปฟรีสำหรับประชาชนทั่วไป"},"answer":"D","category":"Sentence insertion","category_th":"เลือกประโยคให้เข้ากับบริบท","explain_th":"ประโยคก่อนหน้าชวนให้มาเรียนวิธีทำสวนที่ศูนย์ ประโยคถัดไปบอกว่าจะสอนวิธีปลูก rain garden ระหว่างสองประโยคจึงควรเป็นข้อมูลเรื่องคอร์ส/กิจกรรมสอนทำสวน → (D) แจ้งเวิร์กช็อปฟรี","evidence_quotes":["learn how to create a beautiful, eco-friendly garden for your home or business","We will teach you how to plant a rain garden"],"part":6},{"n":132,"options":{"A":"to use","B":"used to","C":"by using","D":"that uses"},"options_th":{"A":"เพื่อจะใช้ (to-infinitive)","B":"เคย (used to + V)","C":"โดยการใช้","D":"ที่ใช้ (relative clause)"},"answer":"D","category":"Subject relative pronoun + verb","category_th":"สรรพนามเชื่อมประโยคแบบประธาน + กริยา","explain_th":"ต้องเชื่อม a shallow sunken garden กับนามวลี a special soil mix ความหมาย 'สวนหลุมตื้นที่ใช้ดินผสมพิเศษ' จึงใช้ relative clause ที่มี a special soil mix เป็นกรรม → (D) that uses  (A) to use ขยายคำนามได้ก็จริงแต่มีความหมายไปทางอนาคต (ที่จะใช้) จึงไม่เหมาะ","evidence_quotes":["a shallow sunken garden [132] a special soil mix"],"part":6},{"n":133,"options":{"A":"Best of all","B":"For example","C":"In any event","D":"As a matter of fact"},"options_th":{"A":"ที่ดีที่สุดคือ, เหนือสิ่งอื่นใด","B":"ตัวอย่างเช่น","C":"ไม่ว่าอย่างไรก็ตาม","D":"อันที่จริง"},"answer":"A","category":"Conjunctive adverb","category_th":"คำเชื่อมประโยค (conjunctive adverb)","explain_th":"ก่อนช่องว่างเป็นการอธิบาย rain garden ทั่ว ๆ ไป หลังช่องว่างเป็นจุดเด่นพิเศษว่าเป็นประโยชน์ต่อสิ่งแวดล้อม จึงต้องใช้คำที่เน้นข้อดีที่โดดเด่น 'ที่ดีที่สุดคือ/เหนือสิ่งอื่นใด' → (A) Best of all  (B) ตัวอย่างเช่น (C) ไม่ว่าอย่างไร (D) อันที่จริง","evidence_quotes":["rain gardens are always beneficial to the local environment"],"part":6},{"n":134,"options":{"A":"we","B":"they","C":"both","D":"yours"},"options_th":{"A":"เรา","B":"พวกมัน (สวนเหล่านั้น)","C":"ทั้งสอง","D":"ของคุณ"},"answer":"B","category":"Pronoun vocabulary","category_th":"คำศัพท์ – สรรพนาม","explain_th":"ช่องว่างเป็นประธานของ improve ประโยคนี้อธิบายข้อดีเพิ่มเติมของ rain gardens ที่กล่าวถึงในประโยคก่อน จึงต้องใช้สรรพนามที่แทน rain gardens → (B) they","evidence_quotes":["rain gardens are always beneficial to the local environment"],"part":6}]},{"set":"135-138","part":6,"type":"letter","passages":[{"label":"letter","text":"31 July\n\nAkwasi Dombo\nFourth Avenue\nGA 105\nAccra, Ghana\n\nDear Mr. Dombo,\n\nThank you for your [135] support in helping me to plan the opening gala for Tokyo’s fashion week. The event was a huge success, and I was honored to work with you. I know that our attendees follow your work closely, and they loved the designs you contributed for this event. Your designs received a lot of [136] on social media. Shows like this will keep Tokyo on the map as a premier fashion centre. [137]. I realize that the multiple delays made the planning no easy task. The auction [138] our Young Designers Award program is coming up soon and I look forward to working with you on that as well.\n\nSincerely,\n\nAsahi Ishioka\nDirector, Japanese Guild of Fashion Designers","text_th":"31 กรกฎาคม\n\nAkwasi Dombo\nFourth Avenue\nGA 105\nAccra, Ghana\n\nเรียน คุณ Dombo\n\nขอบคุณสำหรับการสนับสนุนอัน [135] ที่ช่วยดิฉันวางแผนงานกาล่าเปิดสัปดาห์แฟชั่นโตเกียว งานประสบความสำเร็จอย่างยิ่ง และดิฉันรู้สึกเป็นเกียรติที่ได้ร่วมงานกับคุณ ดิฉันทราบว่าผู้เข้าร่วมงานของเราติดตามผลงานของคุณอย่างใกล้ชิด และพวกเขาชื่นชอบดีไซน์ที่คุณนำมาร่วมในงานนี้มาก ดีไซน์ของคุณได้รับ [136] อย่างมากบนโซเชียลมีเดีย งานแสดงแบบนี้จะช่วยให้โตเกียวยังคงเป็นที่รู้จักในฐานะศูนย์กลางแฟชั่นชั้นนำ [137] ดิฉันเข้าใจดีว่าความล่าช้าหลายครั้งทำให้การวางแผนไม่ใช่เรื่องง่าย งานประมูล [138] โครงการ Young Designers Award ของเรากำลังจะมาถึงในเร็ว ๆ นี้ และดิฉันหวังว่าจะได้ร่วมงานกับคุณในงานนั้นด้วย\n\nขอแสดงความนับถือ\n\nAsahi Ishioka\nผู้อำนวยการ สมาคมนักออกแบบแฟชั่นญี่ปุ่น"}],"vocab":[["gala","งานกาล่า, งานเฉลิมฉลอง"],["be honored","รู้สึกเป็นเกียรติ"],["attendee","ผู้เข้าร่วมงาน"],["closely","อย่างใกล้ชิด"],["contribute","มีส่วนร่วม, นำมาร่วม"],["premier","ชั้นนำ"],["realize","ตระหนัก, เข้าใจ"],["multiple","หลาย"],["planning","การวางแผน"],["auction","การประมูล"],["guild","สมาคม"],["flexibility","ความยืดหยุ่น"],["stop by","แวะมา"],["destination","จุดหมายปลายทาง"]],"questions":[{"n":135,"options":{"A":"amazed","B":"amazement","C":"amazing","D":"amazingly"},"options_th":{"A":"รู้สึกทึ่ง (v-ed)","B":"ความประหลาดใจ (n.)","C":"น่าทึ่ง, ยอดเยี่ยม (v-ing)","D":"อย่างน่าทึ่ง (adv.)"},"answer":"C","category":"Adjective position – present vs. past participle","category_th":"ตำแหน่งคำคุณศัพท์ – present participle vs. past participle","explain_th":"ช่องว่างอยู่ระหว่าง your กับคำนาม support จึงต้องเป็นคำขยายคำนาม ความหมาย 'การสนับสนุนอันยอดเยี่ยม' support เป็นสิ่งที่ทำให้คนอื่นทึ่ง จึงใช้ present participle (C) amazing  (A) amazed ใช้กับผู้ที่รู้สึกทึ่ง support รู้สึกเองไม่ได้ (B) amazement ไม่เป็นคำนามประสมกับ support (D) adv. ใส่ไม่ได้","evidence_quotes":["Thank you for your [135] support"],"part":6},{"n":136,"options":{"A":"attention","B":"proposals","C":"innovation","D":"criticism"},"options_th":{"A":"ความสนใจ","B":"ข้อเสนอ","C":"นวัตกรรม","D":"คำวิจารณ์"},"answer":"A","category":"Noun vocabulary","category_th":"คำศัพท์ – คำนาม","explain_th":"ประโยคก่อนหน้าบอกว่าผู้เข้าร่วมติดตามผลงานของคุณ Dombo อย่างใกล้ชิดและชอบดีไซน์มาก ประโยคนี้จึงควรต่อเนื่องเรื่องเสียงตอบรับดี 'ได้รับความสนใจอย่างมาก' → (A) attention  (B) ข้อเสนอ (C) นวัตกรรม (D) คำวิจารณ์ ไม่เข้าบริบท","evidence_quotes":["they loved the designs you contributed for this event"],"part":6},{"n":137,"options":{"A":"Several other events have gone surprisingly well.","B":"Thank you also for your flexibility in planning the event.","C":"Please stop by our office the next time you are in the city.","D":"Tokyo is a top tourism destination for many reasons."},"options_th":{"A":"งานอื่น ๆ อีกหลายงานก็ดำเนินไปได้ดีอย่างน่าประหลาดใจ","B":"ขอบคุณสำหรับความยืดหยุ่นของคุณในการวางแผนงานนี้ด้วย","C":"ครั้งหน้าที่คุณมาที่เมืองนี้ กรุณาแวะมาที่สำนักงานของเรา","D":"โตเกียวเป็นจุดหมายท่องเที่ยวชั้นนำด้วยเหตุผลหลายประการ"},"answer":"B","category":"Sentence insertion","category_th":"เลือกประโยคให้เข้ากับบริบท","explain_th":"หลังช่องว่างบอกว่า 'เข้าใจว่าความล่าช้าหลายครั้งทำให้การวางแผนไม่ง่าย' แสดงว่าการเตรียมงานไม่ได้เป็นไปตามกำหนด จึงควรมีประโยคขอบคุณที่ยืดหยุ่นรับมือกับการเปลี่ยนแปลงตารางมาก่อน → (B)","evidence_quotes":["I realize that the multiple delays made the planning no easy task."],"part":6},{"n":138,"options":{"A":"will benefit","B":"to benefit","C":"has benefited","D":"benefits"},"options_th":{"A":"จะเป็นประโยชน์ (future)","B":"เพื่อช่วยเหลือ/ที่จะเป็นประโยชน์แก่ (to-infinitive)","C":"ได้เป็นประโยชน์แล้ว (present perfect)","D":"เป็นประโยชน์ (present)"},"answer":"B","category":"To-infinitive as adjective","category_th":"to-infinitive ทำหน้าที่คุณศัพท์","explain_th":"ประโยคมีประธาน The auction และกริยา is coming up ครบแล้ว ช่องว่างจึงต้องเป็นคำที่ขยาย The auction และรับกรรม our Young Designers Award program ได้ → to-infinitive (B) to benefit (งานประมูลเพื่อช่วยโครงการ…) ส่วน (A)(C)(D) เป็นกริยาแท้ ใส่เพิ่มไม่ได้","evidence_quotes":["The auction [138] our Young Designers Award program is coming up soon"],"part":6}]},{"set":"139-142","part":6,"type":"e-mail","passages":[{"label":"e-mail","text":"From: Patron Services <patronservices@menachinlibrary.org>\nTo: Edgar Hughes <hughese98@villachesta.com>\nSubject: Card expiration date approaching\nDate: December 3\n\nDear Mr. Hughes,\n\nPlease be advised that your Mena Chin Library card will expire one month from today.\n\n[139] must be renewed if you intend to keep your membership for the coming year.\n\n[140]. This can be done at the information desk at any branch location.\n\n[141] you decide to close your account, no action is necessary. Failure to complete your renewal by the [142] date will result in the expiration of your library privileges.\n\nIf you have any questions about this notice, or about general library services, you may reply directly to this e-mail.\n\nSincerely,\n\nPatron Services","text_th":"จาก: ฝ่ายบริการสมาชิก <patronservices@menachinlibrary.org>\nถึง: Edgar Hughes <hughese98@villachesta.com>\nเรื่อง: วันหมดอายุบัตรใกล้มาถึง\nวันที่: 3 ธันวาคม\n\nเรียน คุณ Hughes\n\nขอแจ้งให้ทราบว่าบัตรห้องสมุด Mena Chin ของท่านจะหมดอายุในอีกหนึ่งเดือนนับจากวันนี้\n\n[139] ต้องได้รับการต่ออายุหากท่านต้องการคงสถานะสมาชิกในปีหน้า\n\n[140] ซึ่งสามารถทำได้ที่โต๊ะประชาสัมพันธ์ของทุกสาขา\n\n[141] ท่านตัดสินใจจะปิดบัญชี ก็ไม่จำเป็นต้องดำเนินการใด ๆ หากไม่ต่ออายุให้เสร็จภายในวันที่ [142] สิทธิ์การใช้ห้องสมุดของท่านจะหมดอายุ\n\nหากมีคำถามเกี่ยวกับประกาศนี้หรือบริการห้องสมุดทั่วไป ท่านสามารถตอบกลับอีเมลนี้ได้โดยตรง\n\nขอแสดงความนับถือ\n\nฝ่ายบริการสมาชิก"}],"vocab":[["patron","ผู้ใช้บริการ, ลูกค้า"],["expiration","การหมดอายุ"],["approach","ใกล้เข้ามา"],["expire","หมดอายุ"],["renew","ต่ออายุ"],["intend to","ตั้งใจจะ"],["branch","สาขา"],["account","บัญชี (สมาชิก)"],["renewal","การต่ออายุ"],["result in","ส่งผลให้เกิด"],["privilege","สิทธิพิเศษ"],["general","ทั่วไป"],["reply","ตอบกลับ"],["sign up for","สมัคร"],["opt out of","ถอนตัวจาก, เลิกเข้าร่วม"]],"questions":[{"n":139,"options":{"A":"It","B":"You","C":"Our","D":"Each"},"options_th":{"A":"มัน (บัตร)","B":"คุณ","C":"ของเรา","D":"แต่ละ (อัน)"},"answer":"A","category":"Pronoun vocabulary","category_th":"คำศัพท์ – สรรพนาม","explain_th":"ช่องว่างเป็นประธานของ must be renewed ต้องใช้สรรพนามรูปประธาน ประโยคก่อนหน้าแจ้งว่าบัตรห้องสมุดใกล้หมดอายุ สิ่งที่ต้องต่ออายุคือบัตร จึงใช้ (A) It แทน Mena Chin Library card","evidence_quotes":["your Mena Chin Library card will expire one month from today"],"part":6},{"n":140,"options":{"A":"To sign up for a card, visit your local library branch.","B":"For questions about library membership, please visit our Web site.","C":"Renewal must be completed at least one week before your card expires.","D":"You may opt out of this program at any time."},"options_th":{"A":"หากต้องการสมัครบัตร โปรดไปที่ห้องสมุดสาขาใกล้บ้าน","B":"หากมีคำถามเกี่ยวกับการเป็นสมาชิกห้องสมุด โปรดเข้าเว็บไซต์ของเรา","C":"ต้องต่ออายุให้เสร็จอย่างน้อยหนึ่งสัปดาห์ก่อนบัตรหมดอายุ","D":"ท่านสามารถถอนตัวจากโครงการนี้ได้ทุกเมื่อ"},"answer":"C","category":"Sentence insertion","category_th":"เลือกประโยคให้เข้ากับบริบท","explain_th":"ก่อนช่องว่างเตือนว่าบัตรใกล้หมดอายุและต้องต่ออายุหากต้องการเป็นสมาชิกต่อ จึงควรตามด้วยข้อมูลการต่ออายุ ประโยคที่บอกกำหนดเวลาการต่ออายุคือ (C) และประโยคถัดไป This can be done… ก็หมายถึงการต่ออายุ","evidence_quotes":["your Mena Chin Library card will expire one month from today","must be renewed if you intend to keep your membership for the coming year"],"part":6},{"n":141,"options":{"A":"Also","B":"Should","C":"Because","D":"Although"},"options_th":{"A":"นอกจากนี้","B":"หากว่า (If … should – รูป inversion)","C":"เพราะว่า","D":"แม้ว่า"},"answer":"B","category":"Conditional inversion","category_th":"การสลับที่ในประโยคเงื่อนไข (inversion)","explain_th":"ช่องว่างเชื่อมสองประโยคสมบูรณ์ ต้องเป็นคำเชื่อมอนุประโยค ความหมาย 'ถ้าตัดสินใจปิดบัญชี ก็ไม่ต้องทำอะไร' เป็นการสมมุติเหตุการณ์ในอนาคต (If you should decide…) เมื่อละ If จะสลับ should ขึ้นหน้าประธาน → (B) Should","evidence_quotes":["[141] you decide to close your account, no action is necessary."],"part":6},{"n":142,"options":{"A":"specifically","B":"specifics","C":"specified","D":"specificity"},"options_th":{"A":"โดยเฉพาะ (adv.)","B":"รายละเอียด (n.)","C":"ที่ระบุไว้ (v-ed)","D":"ความเฉพาะเจาะจง (n.)"},"answer":"C","category":"Adjective position – past participle","category_th":"ตำแหน่งคำคุณศัพท์ – past participle","explain_th":"ช่องว่างอยู่ระหว่าง the กับคำนาม date ความหมาย 'วันที่ที่ระบุไว้' เป็นความหมายถูกกระทำ → past participle (C) specified  (A) adv. ใส่ไม่ได้ (B) รายละเอียด (D) ความเฉพาะเจาะจง ไม่เป็นคำนามประสมกับ date","evidence_quotes":["by the [142] date"],"part":6}]},{"set":"143-146","part":6,"type":"letter","passages":[{"label":"letter","text":"April 7\n\nNaomi Burwell\n43 Waymire Road\nSouth Portland, ME 04109\n\nDear Ms. Burwell,\n\nI am Omar Ridha, the manager of Droplight Studio. [143]. We offer a full range of photography services for real estate professionals like you. We take pride in composing interior and exterior shots that make a property look its best. Droplight Studio spares no effort in [144] superior digital images. [145], our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property. And once the photo shoot is over, every image [146] expert editing. All these services come standard in every package.\n\nPlease visit our Web site to view our work as well as our pricing and scheduling information. We are happy to work with you to customize orders.\n\nSincerely,\n\nOmar Ridha, Droplight Studio","text_th":"7 เมษายน\n\nNaomi Burwell\n43 Waymire Road\nSouth Portland, ME 04109\n\nเรียน คุณ Burwell\n\nผมชื่อ Omar Ridha ผู้จัดการของ Droplight Studio [143] เราให้บริการถ่ายภาพครบวงจรสำหรับมืออาชีพด้านอสังหาริมทรัพย์อย่างคุณ เราภูมิใจในการจัดองค์ประกอบภาพภายในและภายนอกที่ทำให้อาคารดูดีที่สุด Droplight Studio ทุ่มเทเต็มที่ในการ [144] ภาพดิจิทัลคุณภาพเยี่ยม [145] อุปกรณ์ระดับมืออาชีพ การจัดแสง และเทคนิคการจัดฉากของเราช่วยให้เราเน้นจุดเด่นที่ดีที่สุดของอาคารได้ และเมื่อถ่ายภาพเสร็จ ทุกภาพจะ [146] การแต่งภาพโดยผู้เชี่ยวชาญ บริการทั้งหมดนี้รวมเป็นมาตรฐานอยู่ในทุกแพ็กเกจ\n\nโปรดเข้าชมเว็บไซต์ของเราเพื่อดูผลงาน รวมถึงข้อมูลราคาและตารางเวลา เรายินดีทำงานร่วมกับคุณเพื่อปรับคำสั่งซื้อให้ตรงตามความต้องการ\n\nขอแสดงความนับถือ\n\nOmar Ridha, Droplight Studio"}],"vocab":[["range","ขอบเขต, ความหลากหลาย"],["real estate","อสังหาริมทรัพย์"],["professional","มืออาชีพ"],["take pride in","ภูมิใจใน"],["compose","จัดองค์ประกอบ"],["interior","ภายใน"],["exterior","ภายนอก"],["shot","ภาพถ่าย"],["property","อาคาร, อสังหาริมทรัพย์"],["spare no effort","ทุ่มเทเต็มที่"],["superior","เหนือกว่า, คุณภาพเยี่ยม"],["grade","ระดับ"],["staging","การจัดฉาก/ตกแต่งเพื่อถ่ายภาพ"],["highlight","เน้น"],["feature","จุดเด่น, ลักษณะ"],["expert","ของผู้เชี่ยวชาญ"],["customize","ปรับให้ตรงความต้องการ"],["stand out","โดดเด่น"],["of its kind","ในประเภทเดียวกัน"]],"questions":[{"n":143,"options":{"A":"I would like to introduce you to our business.","B":"Great photographs can make your property stand out.","C":"We are looking forward to your visit.","D":"It was the first studio of its kind to open in this area."},"options_th":{"A":"ผมขอแนะนำธุรกิจของเราให้คุณรู้จัก","B":"ภาพถ่ายที่ยอดเยี่ยมทำให้อาคารของคุณโดดเด่นได้","C":"เราตั้งตารอการมาเยือนของคุณ","D":"เป็นสตูดิโอประเภทนี้แห่งแรกที่เปิดในพื้นที่นี้"},"answer":"A","category":"Sentence insertion","category_th":"เลือกประโยคให้เข้ากับบริบท","explain_th":"ก่อนช่องว่างผู้เขียนแนะนำตัวว่าเป็นผู้จัดการ Droplight Studio หลังช่องว่างอธิบายว่าให้บริการถ่ายภาพสำหรับมืออาชีพอสังหาฯ เนื้อหาโดยรวมคือการแนะนำธุรกิจเพื่อหาลูกค้าใหม่ → (A)","evidence_quotes":["I am Omar Ridha, the manager of Droplight Studio.","We offer a full range of photography services for real estate professionals like you."],"part":6},{"n":144,"options":{"A":"researching","B":"creating","C":"purchasing","D":"displaying"},"options_th":{"A":"ค้นคว้า","B":"สร้าง","C":"ซื้อ","D":"จัดแสดง"},"answer":"B","category":"Verb vocabulary","category_th":"คำศัพท์ – คำกริยา","explain_th":"ประโยคก่อนพูดถึงความภูมิใจในการถ่ายภาพให้อาคารดูดี ประโยคหลังพูดถึงอุปกรณ์และเทคนิค จึงควรเป็น 'ทุ่มเทเต็มที่ในการสร้างภาพดิจิทัลคุณภาพเยี่ยม' → (B) creating  (A) ค้นคว้า (C) ซื้อ (D) จัดแสดง","evidence_quotes":["We take pride in composing interior and exterior shots that make a property look its best."],"part":6},{"n":145,"options":{"A":"If not","B":"By comparison","C":"Otherwise","D":"Indeed"},"options_th":{"A":"ถ้าไม่ใช่","B":"เมื่อเปรียบเทียบกัน","C":"มิฉะนั้น","D":"แท้จริงแล้ว, จริง ๆ"},"answer":"D","category":"Conjunctive adverb","category_th":"คำเชื่อมประโยค (conjunctive adverb)","explain_th":"ประโยคก่อนบอกว่าทุ่มเทสร้างภาพคุณภาพดี ประโยคหลังยกรายละเอียดมาสนับสนุนและเน้นย้ำ (อุปกรณ์ แสง เทคนิค) จึงใช้คำที่เสริมเน้นข้อความเดิม → (D) Indeed  (A) ถ้าไม่ใช่ (B) เมื่อเทียบกัน (C) มิฉะนั้น","evidence_quotes":["our professional-grade equipment, lighting, and staging techniques allow us to highlight the best features of a property"],"part":6},{"n":146,"options":{"A":"receives","B":"is receiving","C":"had received","D":"had to receive"},"options_th":{"A":"ได้รับ (present simple)","B":"กำลังได้รับ (present continuous)","C":"ได้รับแล้ว (past perfect)","D":"ต้องได้รับ (อดีต)"},"answer":"A","category":"Verb form – tense","category_th":"รูปกริยา – กาล","explain_th":"ทั้งข้อความอธิบายบริการของสตูดิโอด้วย present simple (ข้อเท็จจริงทั่วไป) ประโยคนี้ก็ควรเป็น present simple 'ทุกภาพจะได้รับการแต่งโดยผู้เชี่ยวชาญ' → (A) receives","evidence_quotes":["All these services come standard in every package."],"part":6}]}],"7":[{"set":"147-148","part":7,"type":"information","passages":[{"label":"information","text":"STOP! PLEASE READ FIRST.\n\nThank you for purchasing this item.\n\nAs you do the unpacking, please verify that all components are included and place them in a safe area to avoid loss or damage. Assemble the item on a soft surface or on the flattened empty box.\n\nFollow the pictures and begin the assembly by placing the main part on its side. Never overtighten any screws or bolts, or you may damage the wood or cushioning. Please visit our Web site to obtain maintenance tips and register your product for warranty coverage: www.indoordelight.com.","text_th":"หยุด! โปรดอ่านก่อน\n\nขอบคุณที่ซื้อสินค้านี้\n\nขณะแกะกล่อง โปรดตรวจสอบว่ามีชิ้นส่วนครบทุกชิ้น และวางไว้ในที่ปลอดภัยเพื่อป้องกันการสูญหายหรือเสียหาย ประกอบสินค้าบนพื้นผิวที่นุ่มหรือบนกล่องเปล่าที่แผ่ราบแล้ว\n\nทำตามรูปภาพและเริ่มประกอบโดยวางชิ้นส่วนหลักตะแคงข้าง ห้ามขันสกรูหรือน็อตแน่นเกินไป มิฉะนั้นอาจทำให้ไม้หรือเบาะเสียหายได้ โปรดเข้าเว็บไซต์ของเราเพื่อดูเคล็ดลับการดูแลรักษา และลงทะเบียนสินค้าเพื่อรับการรับประกัน: www.indoordelight.com"}],"vocab":[["unpack","แกะของออกจากกล่อง"],["verify","ตรวจสอบ, ยืนยัน"],["component","ชิ้นส่วน"],["loss","การสูญหาย"],["damage","ความเสียหาย; ทำให้เสียหาย"],["assemble","ประกอบ"],["surface","พื้นผิว"],["flattened","ที่แผ่ราบ"],["assembly","การประกอบ"],["overtighten","ขันแน่นเกินไป"],["screw","สกรู"],["cushioning","เบาะ, วัสดุกันกระแทก"],["obtain","ได้รับ"],["maintenance","การดูแลรักษา"],["register","ลงทะเบียน"],["warranty","การรับประกัน"],["coverage","ความคุ้มครอง"]],"questions":[{"n":147,"question":"Where is the information most likely found?","question_th":"ข้อมูลนี้น่าจะพบได้ที่ไหน","type":"inference","options":{"A":"On a door","B":"On a receipt","C":"In a box","D":"On a Web site"},"options_th":{"A":"บนประตู","B":"บนใบเสร็จ","C":"ในกล่อง","D":"บนเว็บไซต์"},"answer":"C","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"ประโยคแรกขอบคุณที่ซื้อสินค้า ย่อหน้าที่สองให้ตรวจสอบชิ้นส่วนขณะแกะกล่อง และให้ประกอบบนพื้นนุ่มหรือบนกล่องเปล่าที่แผ่ราบ จึงอนุมานได้ว่าเป็นคู่มือที่อยู่ในกล่องสินค้า → (C)","evidence_quotes":["Thank you for purchasing this item.","As you do the unpacking, please verify that all components are included","Assemble the item on a soft surface or on the flattened empty box."],"paraphrase":[],"part":7},{"n":148,"question":"What kind of item is most likely discussed?","question_th":"สินค้าที่กล่าวถึงน่าจะเป็นสินค้าประเภทใด","type":"inference","options":{"A":"A desktop computer","B":"A piece of furniture","C":"A household appliance","D":"A power tool"},"options_th":{"A":"คอมพิวเตอร์ตั้งโต๊ะ","B":"เฟอร์นิเจอร์","C":"เครื่องใช้ไฟฟ้าในบ้าน","D":"เครื่องมือไฟฟ้า"},"answer":"B","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"ย่อหน้าที่สามให้เริ่มประกอบตามรูปโดยวางชิ้นส่วนหลักตะแคงข้าง และห้ามขันสกรู/น็อตแน่นเกิน มิฉะนั้นไม้หรือเบาะจะเสียหาย จึงเป็นสินค้าที่ต้องประกอบ มีไม้และเบาะ → เฟอร์นิเจอร์ (B)","evidence_quotes":["Follow the pictures and begin the assembly by placing the main part on its side.","Never overtighten any screws or bolts, or you may damage the wood or cushioning."],"part":7}]},{"set":"149-150","part":7,"type":"schedule","passages":[{"label":"meeting schedule","text":"We are asking all Winnipeg staff to keep a copy of this schedule at their desks as a quick reference tool for scheduling interoffice meetings. Whenever possible, please schedule these meetings during one of the underlined hours, that is, after 7:00 A.M. but before 11:00 A.M.\n\nWinnipeg | Toulouse\n7:00 A.M. (underlined) | 2:00 P.M.\n8:00 A.M. (underlined) | 3:00 P.M.\n9:00 A.M. (underlined) | 4:00 P.M.\n10:00 A.M. (underlined) | 5:00 P.M.\n11:00 A.M. | 6:00 P.M.\n12:00 noon | 7:00 P.M.","text_th":"เราขอให้พนักงานที่ Winnipeg ทุกคนเก็บสำเนาตารางนี้ไว้ที่โต๊ะทำงาน เพื่อใช้อ้างอิงอย่างรวดเร็วเวลานัดประชุมระหว่างสำนักงาน หากเป็นไปได้ โปรดนัดประชุมในช่วงเวลาที่ขีดเส้นใต้ไว้ คือหลัง 7:00 น. แต่ก่อน 11:00 น.\n\nWinnipeg | Toulouse\n7:00 น. (ขีดเส้นใต้) | 14:00 น.\n8:00 น. (ขีดเส้นใต้) | 15:00 น.\n9:00 น. (ขีดเส้นใต้) | 16:00 น.\n10:00 น. (ขีดเส้นใต้) | 17:00 น.\n11:00 น. | 18:00 น.\n12:00 น. (เที่ยง) | 19:00 น.","image":"img/rc_t01_149-150_1.png"}],"vocab":[["reference","การอ้างอิง"],["tool","เครื่องมือ"],["interoffice","ระหว่างสำนักงาน"],["underlined","ที่ขีดเส้นใต้"],["time zone","เขตเวลา"],["administrative","ด้านธุรการ"]],"questions":[{"n":149,"question":"What is suggested by the schedule?","question_th":"ตารางนี้บอกเป็นนัยถึงอะไร","type":"inference","options":{"A":"A conference has been scheduled.","B":"A firm has offices in two time zones.","C":"Administrative assistants make travel plans.","D":"Some meeting times have been changed."},"options_th":{"A":"มีการกำหนดการประชุมใหญ่ไว้แล้ว","B":"บริษัทมีสำนักงานอยู่ในสองเขตเวลา","C":"ผู้ช่วยฝ่ายธุรการเป็นผู้วางแผนการเดินทาง","D":"เวลาประชุมบางช่วงถูกเปลี่ยน"},"answer":"B","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"ประโยคแรกขอให้พนักงาน Winnipeg เก็บตารางไว้ใช้นัดประชุมระหว่างสำนักงาน และตารางแสดงเวลาของสองสำนักงานคือ Winnipeg และ Toulouse ที่ต่างกัน จึงอนุมานได้ว่าบริษัทมีสำนักงานอยู่สองเขตเวลา → (B)","evidence_quotes":["We are asking all Winnipeg staff to keep a copy of this schedule at their desks as a quick reference tool for scheduling interoffice meetings.","Winnipeg | Toulouse"],"part":7},{"n":150,"question":"What is indicated about 11:00 A.M. Winnipeg time?","question_th":"ข้อใดบอกเป็นนัยเกี่ยวกับเวลา 11:00 น. ตามเวลา Winnipeg","type":"inference","options":{"A":"It is when the Winnipeg office closes for lunch.","B":"It is when staff in Toulouse begin their workday.","C":"It is not a preferred time to schedule a meeting.","D":"It has just been added to the schedule."},"options_th":{"A":"เป็นเวลาที่สำนักงาน Winnipeg ปิดพักกลางวัน","B":"เป็นเวลาที่พนักงานใน Toulouse เริ่มงาน","C":"ไม่ใช่เวลาที่ควรนัดประชุม","D":"เพิ่งถูกเพิ่มเข้าไปในตาราง"},"answer":"C","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"ประโยคที่สองขอให้นัดประชุมในช่วงที่ขีดเส้นใต้ คือหลัง 7:00 แต่ก่อน 11:00 และ 11:00 A.M. ของ Winnipeg ไม่ได้ขีดเส้นใต้ จึงไม่ใช่เวลาที่แนะนำให้นัดประชุม → (C)","evidence_quotes":["Whenever possible, please schedule these meetings during one of the underlined hours, that is, after 7:00 A.M. but before 11:00 A.M."],"part":7}]},{"set":"151-152","part":7,"type":"brochure","passages":[{"label":"brochure","text":"The Bryant Foyer is one of the premier event spaces in our area. Set on a hill, it has expansive windows that provide sweeping views of the adjacent botanical gardens and the river. Built in 1897, it was the home of the Francona Charitable Trust until its renovation just over a year ago. Today, the space can accommodate up to 200 guests and is ideal for wedding receptions, office parties, and panel presentations. With its marble floors, cathedral ceiling, and stunning artwork, the Bryant Foyer is the ideal location for your next gathering.\n\nThe on-site restaurant, Andito’s, caters our events and also operates as its own business. This farm-to-table restaurant, headed by chef Michaela Rymond, meets all dietary needs and has revolutionized the local food scene. Area residents know to plan far in advance to get a seat.\n\nTo reserve the event space or to make a dinner reservation, give us a call at 216-555-0157.","text_th":"Bryant Foyer เป็นหนึ่งในสถานที่จัดงานชั้นนำในพื้นที่ของเรา ตั้งอยู่บนเนินเขา มีหน้าต่างกว้างที่มองเห็นวิวสวนพฤกษศาสตร์และแม่น้ำที่อยู่ติดกันได้อย่างกว้างไกล สร้างขึ้นในปี 1897 และเคยเป็นที่ทำการของ Francona Charitable Trust จนกระทั่งได้รับการปรับปรุงใหม่เมื่อปีกว่าที่ผ่านมา ปัจจุบันสถานที่นี้รองรับแขกได้ถึง 200 คน และเหมาะสำหรับงานเลี้ยงฉลองแต่งงาน งานเลี้ยงบริษัท และการนำเสนอแบบเสวนา ด้วยพื้นหินอ่อน เพดานสูงแบบมหาวิหาร และงานศิลปะที่สวยงามน่าทึ่ง Bryant Foyer จึงเป็นสถานที่ในอุดมคติสำหรับงานสังสรรค์ครั้งต่อไปของคุณ\n\nAndito’s ร้านอาหารภายในสถานที่ ให้บริการอาหารสำหรับงานของเรา และยังเปิดเป็นร้านอาหารของตัวเองด้วย ร้านอาหารแบบ farm-to-table (จากฟาร์มสู่โต๊ะอาหาร) แห่งนี้ ซึ่งมีเชฟ Michaela Rymond เป็นหัวหน้า รองรับความต้องการด้านอาหารทุกรูปแบบ และได้ปฏิวัติวงการอาหารในท้องถิ่น ผู้อยู่อาศัยในพื้นที่รู้ดีว่าต้องวางแผนจองล่วงหน้านานมากจึงจะได้ที่นั่ง\n\nหากต้องการจองสถานที่จัดงานหรือจองโต๊ะสำหรับมื้อค่ำ โทรหาเราที่ 216-555-0157"}],"vocab":[["premier","ชั้นนำ"],["expansive","กว้างขวาง"],["sweeping","กว้างไกล (วิว)"],["adjacent","ที่อยู่ติดกัน"],["botanical garden","สวนพฤกษศาสตร์"],["charitable","เพื่อการกุศล"],["trust","มูลนิธิ, ทรัสต์"],["renovation","การปรับปรุงใหม่"],["accommodate","รองรับ (จำนวนคน)"],["ideal","เหมาะที่สุด"],["marble","หินอ่อน"],["cathedral ceiling","เพดานสูงแบบหน้าจั่ว"],["stunning","สวยงามน่าทึ่ง"],["gathering","การรวมตัว, งานสังสรรค์"],["on-site","ภายในสถานที่"],["cater","จัดเลี้ยง, ให้บริการอาหาร"],["operate","ดำเนินกิจการ"],["dietary","เกี่ยวกับอาหาร"],["revolutionize","ปฏิวัติ, เปลี่ยนแปลงครั้งใหญ่"],["scene","วงการ"],["resident","ผู้อยู่อาศัย"],["in advance","ล่วงหน้า"],["reserve","จอง"],["shore","ชายฝั่ง"],["solely","เท่านั้น"],["fund","ให้เงินทุน"],["organization","องค์กร"]],"questions":[{"n":151,"question":"What is indicated about the Bryant Foyer?","question_th":"ข้อใดกล่าวถึง Bryant Foyer ได้ถูกต้อง","type":"not-true","options":{"A":"It is located on the shores of a lake.","B":"It has recently been renovated.","C":"It will build a botanical garden for guests.","D":"It is reserved solely for corporate events."},"options_th":{"A":"ตั้งอยู่ริมทะเลสาบ","B":"เพิ่งได้รับการปรับปรุงใหม่","C":"จะสร้างสวนพฤกษศาสตร์สำหรับแขก","D":"รับจองเฉพาะงานของบริษัทเท่านั้น"},"answer":"B","category":"Not/True","category_th":"Not/True (ข้อใดถูก/ไม่ถูก)","explain_th":"ประโยคที่สามบอกว่าสร้างปี 1897 และเป็นที่ทำการของมูลนิธิจนได้รับการปรับปรุงเมื่อปีกว่าที่แล้ว → (B) ถูก  ส่วนประโยคที่สองบอกว่าตั้งบนเนินเขาและมองเห็นสวนพฤกษศาสตร์กับแม่น้ำ ตัด (A)(C) และประโยคที่สี่บอกว่าเหมาะทั้งงานแต่งงาน งานเลี้ยงบริษัท และการเสวนา ตัด (D)","evidence_quotes":["Built in 1897, it was the home of the Francona Charitable Trust until its renovation just over a year ago."],"paraphrase":[["just over a year ago","recently"]],"part":7},{"n":152,"question":"What is suggested about Andito’s?","question_th":"ข้อใดบอกเป็นนัยเกี่ยวกับ Andito’s","type":"inference","options":{"A":"It was started by an international chef.","B":"It offers limited menu options.","C":"It is now funded by a charitable organization.","D":"It is very popular with local residents."},"options_th":{"A":"ก่อตั้งโดยเชฟระดับนานาชาติ","B":"มีตัวเลือกเมนูจำกัด","C":"ปัจจุบันได้รับเงินทุนจากองค์กรการกุศล","D":"เป็นที่นิยมมากในหมู่คนในท้องถิ่น"},"answer":"D","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"ประโยคสุดท้ายของย่อหน้าที่แนะนำ Andito’s บอกว่าคนในพื้นที่รู้ว่าต้องวางแผนล่วงหน้านานจึงจะได้ที่นั่ง แสดงว่าร้านนี้ได้รับความนิยมมากจากคนท้องถิ่น → (D)","evidence_quotes":["Area residents know to plan far in advance to get a seat."],"part":7}]},{"set":"153-154","part":7,"type":"text-message chain","passages":[{"label":"text-message chain","text":"Joan Chi (12:39 P.M.): Hello Mina. Are you almost finished with the field measurements? I’m getting hungry.\nMina Evers (12:40 P.M.): Sorry, Joan. I’m afraid you and Ms. Lim will have to go to lunch without me today. There’s a problem with the site coordinates. This is going to take some time.\nJoan Chi (12:51 P.M.): Oh no. Should we bring something back for you?\nMina Evers (12:59 P.M.): Get me a chicken sandwich.\nJoan Chi (1:00 P.M.): Sure thing, Mina. See you in a while.","text_th":"Joan Chi (12:39 น.): สวัสดี Mina วัดพื้นที่ภาคสนามใกล้เสร็จหรือยัง ฉันเริ่มหิวแล้ว\nMina Evers (12:40 น.): ขอโทษนะ Joan สงสัยวันนี้เธอกับคุณ Lim ต้องไปกินข้าวกลางวันกันโดยไม่มีฉันแล้วล่ะ พิกัดของไซต์งานมีปัญหา คงต้องใช้เวลาสักพัก\nJoan Chi (12:51 น.): แย่จัง ให้ซื้ออะไรกลับมาให้ไหม\nMina Evers (12:59 น.): ขอแซนด์วิชไก่หนึ่งชิ้น\nJoan Chi (13:00 น.): ได้เลย Mina แล้วเจอกันอีกสักพักนะ"}],"vocab":[["field","ภาคสนาม, หน้างาน"],["measurement","การวัด"],["site","สถานที่, ไซต์งาน"],["coordinate","พิกัด"]],"questions":[{"n":153,"question":"At 1:00 P.M., what does Ms. Chi most likely mean when she writes, “Sure thing, Mina”?","question_th":"เวลา 13:00 น. คุณ Chi น่าจะหมายความว่าอะไรเมื่อเขียนว่า “Sure thing, Mina”","type":"intent","options":{"A":"She will bring lunch for Ms. Evers.","B":"She can provide a tool that Ms. Evers needs.","C":"Some site coordinates are correct.","D":"Some measurements must be double-checked."},"options_th":{"A":"เธอจะนำอาหารกลางวันมาให้คุณ Evers","B":"เธอสามารถจัดหาเครื่องมือที่คุณ Evers ต้องการได้","C":"พิกัดไซต์งานบางจุดถูกต้อง","D":"ต้องตรวจสอบการวัดบางส่วนซ้ำ"},"answer":"A","category":"Writer’s intent","category_th":"เจตนาของผู้เขียน","explain_th":"12:40 Evers บอกว่า Chi กับ Lim ต้องไปกินข้าวโดยไม่มีเธอ 12:51 Chi ถามว่าจะซื้ออะไรกลับมาให้ไหม 12:59 Evers ขอแซนด์วิชไก่ และ 13:00 Chi ตอบว่า 'Sure thing, Mina' จึงหมายถึงจะซื้อแซนด์วิชไก่เป็นอาหารกลางวันมาให้ → (A)","evidence_quotes":["I’m afraid you and Ms. Lim will have to go to lunch without me today.","Should we bring something back for you?","Get me a chicken sandwich."],"part":7},{"n":154,"question":"What will happen next?","question_th":"จะเกิดอะไรขึ้นต่อไป","type":"detail","options":{"A":"Ms. Chi will get new site coordinates.","B":"Ms. Chi and Ms. Lim will be out for a while.","C":"Ms. Evers will share a recipe.","D":"Ms. Lim will begin taking measurements."},"options_th":{"A":"คุณ Chi จะได้พิกัดไซต์งานใหม่","B":"คุณ Chi และคุณ Lim จะออกไปข้างนอกสักพัก","C":"คุณ Evers จะแบ่งปันสูตรอาหาร","D":"คุณ Lim จะเริ่มวัดพื้นที่"},"answer":"B","category":"Detail","category_th":"รายละเอียด","explain_th":"12:40 Evers บอกว่า Chi กับ Lim ต้องไปกินข้าวกลางวันโดยไม่มีเธอ และ 13:00 Chi บอกว่า 'See you in a while' แสดงว่า Chi กับ Lim กำลังจะออกไปกินข้าวข้างนอกสักพัก → (B)","evidence_quotes":["I’m afraid you and Ms. Lim will have to go to lunch without me today.","See you in a while."],"paraphrase":[["go to lunch","be out for a while"]],"part":7}]},{"set":"155-157","part":7,"type":"notice","passages":[{"label":"notice","text":"This season’s excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for. Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden’s Web site (www.vfgrdn.org), where you will find our list of drop-off locations.\n\nIf you need us to come to you instead, please contact us. We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it. Check our Web site for more information about this service as well as for insights into topics related to farming and gardening in the Northern Great Plains region.","text_th":"สภาพอากาศที่ดีเยี่ยมในฤดูกาลนี้ทำให้ได้ผลผลิตผักและผลไม้จำนวนมาก ในหลายกรณีมากเกินกว่าที่ผู้ปลูกจะหาผู้ซื้อได้ ท่านที่ต้องการบริจาคผลผลิตส่วนเกินให้กับองค์กรชุมชนสามารถทำได้โดยเข้าเว็บไซต์ของ Vosey Farm and Garden (www.vfgrdn.org) ซึ่งมีรายชื่อจุดรับฝากของ\n\nหากต้องการให้เราไปรับถึงที่แทน โปรดติดต่อเรา เราจะติดต่อคนขับรถบรรทุกอิสระคนใดคนหนึ่งจากหลายคนที่อาสาช่วยขนส่งและกระจายอาหารที่ท่านบริจาคไปยังกลุ่มที่ผ่านการตรวจสอบแล้วและต้องการอาหารอย่างรวดเร็ว ดูข้อมูลเพิ่มเติมเกี่ยวกับบริการนี้ รวมถึงความรู้ในหัวข้อเกี่ยวกับการทำฟาร์มและการทำสวนในภูมิภาค Northern Great Plains ได้ที่เว็บไซต์ของเรา"}],"vocab":[["yield","ให้ผลผลิต"],["substantial","จำนวนมาก"],["harvest","ผลผลิต, การเก็บเกี่ยว"],["donate","บริจาค"],["surplus","ส่วนเกิน"],["produce","ผลผลิตทางการเกษตร"],["organization","องค์กร"],["drop-off","จุดส่ง/วางของ"],["reach out to","ติดต่อ"],["independent","อิสระ"],["transport","ขนส่ง"],["distribute","แจกจ่าย, กระจาย"],["donation","ของบริจาค"],["vetted","ผ่านการตรวจสอบแล้ว"],["insight","ความรู้ความเข้าใจ"],["related to","เกี่ยวข้องกับ"],["Great Plains","ที่ราบใหญ่ (ทางตะวันออกของเทือกเขาร็อกกี)"],["transportation","การขนส่ง"],["heavy","มาก, หนัก (ฝน)"],["frequently","บ่อย ๆ"],["beneficial","เป็นประโยชน์"],["crop","พืชผล"],["staffing","การจัดหาพนักงาน"],["distribution","การแจกจ่าย"],["machinery","เครื่องจักร"]],"questions":[{"n":155,"question":"For whom is the notice most likely intended?","question_th":"ประกาศนี้น่าจะมีไว้สำหรับใคร","type":"inference","options":{"A":"Farmers","B":"Professional chefs","C":"Truck drivers","D":"Supermarket managers"},"options_th":{"A":"เกษตรกร","B":"เชฟมืออาชีพ","C":"คนขับรถบรรทุก","D":"ผู้จัดการซูเปอร์มาร์เก็ต"},"answer":"A","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"ประโยคแรกบอกว่าอากาศดีจนผลผลิตมากเกินกว่าที่ผู้ปลูกจะหาผู้ซื้อได้ ประโยคที่สองบอกว่าผู้ที่ต้องการบริจาคผลผลิตส่วนเกินให้ดูจุดรับฝากในเว็บไซต์ จึงอนุมานได้ว่าประกาศนี้มีไว้สำหรับผู้ผลิตพืชผลโดยตรง คือเกษตรกร → (A)","evidence_quotes":["This season’s excellent weather has yielded a substantial harvest of fruits and vegetables, in many cases more than growers may find buyers for.","Those of you wishing to donate surplus produce to community organizations can do so by visiting Vosey Farm and Garden’s Web site (www.vfgrdn.org), where you will find our list of drop-off locations."],"part":7},{"n":156,"question":"What does the notice indicate about the weather?","question_th":"ประกาศระบุอะไรเกี่ยวกับสภาพอากาศ","type":"not-true","options":{"A":"It caused transportation delays.","B":"It included heavier rain than usual.","C":"It was frequently a topic in the local news.","D":"It was beneficial for crops."},"options_th":{"A":"ทำให้การขนส่งล่าช้า","B":"มีฝนตกหนักกว่าปกติ","C":"เป็นหัวข้อข่าวท้องถิ่นบ่อย ๆ","D":"เป็นประโยชน์ต่อพืชผล"},"answer":"D","category":"Not/True","category_th":"Not/True (ข้อใดถูก/ไม่ถูก)","explain_th":"ประโยคแรกบอกว่าอากาศดีเยี่ยมทำให้ได้ผลผลิตผักผลไม้มากจนเกินกว่าที่ผู้ปลูกจะหาผู้ซื้อได้ แสดงว่าอากาศเป็นประโยชน์ต่อพืชผล → (D)","evidence_quotes":["This season’s excellent weather has yielded a substantial harvest of fruits and vegetables"],"paraphrase":[["fruits and vegetables","crops"]],"part":7},{"n":157,"question":"What service does the notice mention?","question_th":"ประกาศกล่าวถึงบริการอะไร","type":"not-true","options":{"A":"Staffing for local businesses","B":"Food collection and distribution","C":"Farm machinery repair","D":"Gardening workshops"},"options_th":{"A":"การจัดหาพนักงานให้ธุรกิจท้องถิ่น","B":"การรับและแจกจ่ายอาหาร","C":"การซ่อมเครื่องจักรกลการเกษตร","D":"เวิร์กช็อปการทำสวน"},"answer":"B","category":"Not/True","category_th":"Not/True (ข้อใดถูก/ไม่ถูก)","explain_th":"ย่อหน้าที่สองบอกว่าจะติดต่อคนขับรถบรรทุกอาสาให้มาขนและกระจายอาหารบริจาคไปยังกลุ่มที่ต้องการ จึงเป็นบริการรับและแจกจ่ายอาหาร → (B)","evidence_quotes":["We will reach out to one of the many independent truck drivers who have kindly volunteered to transport and quickly distribute your food donations to vetted groups that need it."],"paraphrase":[["transport and distribute","collection and distribution"]],"part":7}]},{"set":"158-160","part":7,"type":"notice","passages":[{"label":"notice","text":"We are delighted that you are joining us for today’s event. — [1] —. We ask that you adhere to the following guidelines to ensure that all attendees have an enjoyable experience.\n\nUpon entering the venue, please put any and all electronic devices in silent mode. Ringtones and lit screens are very distracting to both the performers and your fellow audience members. — [2] —. Moreover, audience members are not allowed to make an audio or visual recording of the performance.\n\nBags and other items in the aisles pose a safety concern. — [3] —. If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2. — [4] —. One of our attendants will gladly assist you with that.\n\nThank you for your cooperation.","text_th":"เรายินดีอย่างยิ่งที่ท่านมาร่วมงานกับเราในวันนี้ — [1] — เราขอให้ท่านปฏิบัติตามแนวทางต่อไปนี้ เพื่อให้ผู้เข้าร่วมทุกคนได้รับประสบการณ์ที่น่าประทับใจ\n\nเมื่อเข้าสู่สถานที่จัดงาน โปรดปรับอุปกรณ์อิเล็กทรอนิกส์ทุกชนิดเป็นโหมดเงียบ เสียงเรียกเข้าและหน้าจอที่สว่างรบกวนทั้งนักแสดงและผู้ชมคนอื่น ๆ อย่างมาก — [2] — นอกจากนี้ ผู้ชมไม่ได้รับอนุญาตให้บันทึกเสียงหรือบันทึกภาพการแสดง\n\nกระเป๋าและสิ่งของอื่น ๆ ที่วางอยู่บนทางเดินอาจก่อให้เกิดปัญหาด้านความปลอดภัย — [3] — หากกระเป๋าของท่านใหญ่เกินกว่าจะวางใต้ที่นั่งได้พอดี โปรดพิจารณาฝากไว้ในล็อกเกอร์ในราคาเพียง 2 ดอลลาร์ — [4] — เจ้าหน้าที่ของเรายินดีช่วยเหลือท่านในเรื่องนี้\n\nขอบคุณสำหรับความร่วมมือ"}],"vocab":[["delighted","ยินดีมาก"],["adhere to","ปฏิบัติตาม"],["attendee","ผู้เข้าร่วม"],["venue","สถานที่จัดงาน"],["device","อุปกรณ์"],["silent","เงียบ"],["ringtone","เสียงเรียกเข้า"],["lit","ที่สว่าง, ที่เปิดไฟ"],["distracting","ที่รบกวนสมาธิ"],["fellow","ที่อยู่ในสถานะเดียวกัน, เพื่อน (ผู้ชมด้วยกัน)"],["aisle","ทางเดิน"],["pose","ก่อให้เกิด (ปัญหา)"],["properly","อย่างเหมาะสม, พอดี"],["store","เก็บ, ฝาก"],["attendant","เจ้าหน้าที่, พนักงานดูแล"],["cooperation","ความร่วมมือ"],["inspect","ตรวจสอบ"],["refrain from","งดเว้นจาก"]],"questions":[{"n":158,"question":"Where most likely is the notice posted?","question_th":"ประกาศนี้น่าจะติดอยู่ที่ไหน","type":"inference","options":{"A":"In an airplane","B":"In a concert hall","C":"At a restaurant","D":"At a post office"},"options_th":{"A":"ในเครื่องบิน","B":"ในหอแสดงดนตรี","C":"ที่ร้านอาหาร","D":"ที่ที่ทำการไปรษณีย์"},"answer":"B","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"ย่อหน้าที่สองขอให้ปิดเสียงอุปกรณ์ทุกชนิดเมื่อเข้าสถานที่ และบอกว่าเสียงเรียกเข้าและหน้าจอที่สว่างรบกวนทั้งนักแสดงและผู้ชม จึงน่าจะติดอยู่ในสถานที่แสดง → (B) หอแสดงดนตรี","evidence_quotes":["Upon entering the venue, please put any and all electronic devices in silent mode.","Ringtones and lit screens are very distracting to both the performers and your fellow audience members."],"part":7},{"n":159,"question":"What is stated about large bags?","question_th":"ข้อใดกล่าวถึงกระเป๋าขนาดใหญ่","type":"not-true","options":{"A":"They can be put in a locked box for a fee.","B":"They must be left outside the building.","C":"They will be inspected by an attendant.","D":"They must be stored under a seat."},"options_th":{"A":"สามารถฝากไว้ในตู้ที่ล็อกได้โดยเสียค่าบริการ","B":"ต้องวางไว้นอกอาคาร","C":"จะถูกตรวจโดยเจ้าหน้าที่","D":"ต้องเก็บไว้ใต้ที่นั่ง"},"answer":"A","category":"Not/True","category_th":"Not/True (ข้อใดถูก/ไม่ถูก)","explain_th":"ย่อหน้าที่สามบอกว่าถ้ากระเป๋าใหญ่เกินกว่าจะวางใต้ที่นั่ง ให้พิจารณาฝากไว้ในล็อกเกอร์ในราคาเพียง 2 ดอลลาร์ → (A)","evidence_quotes":["If your bag is too big to fit properly under a seat, consider storing it in a locker for just $2."],"paraphrase":[["a locker for just $2","a locked box for a fee"]],"part":7},{"n":160,"question":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“Please refrain from making phone calls or texting at all times.”","question_th":"ประโยคต่อไปนี้ควรอยู่ในตำแหน่งใดมากที่สุดในบรรดา [1] [2] [3] และ [4]\n“โปรดงดการโทรศัพท์หรือส่งข้อความตลอดเวลา”","type":"insert","options":{"A":"[1]","B":"[2]","C":"[3]","D":"[4]"},"options_th":{"A":"[1]","B":"[2]","C":"[3]","D":"[4]"},"answer":"B","category":"Sentence insertion","category_th":"การแทรกประโยค","explain_th":"ประโยคที่ให้มาขอให้งดโทรศัพท์และส่งข้อความ ซึ่งเป็นพฤติกรรมที่ต้องระวัง จึงควรอยู่ระหว่างประโยคที่ว่าเสียงเรียกเข้าและหน้าจอที่สว่างรบกวนนักแสดงและผู้ชม กับประโยคที่ว่าผู้ชมห้ามบันทึกเสียงหรือภาพ ซึ่งเป็นข้อห้ามต่อเนื่องกัน → [2] (B)","evidence_quotes":["Ringtones and lit screens are very distracting to both the performers and your fellow audience members.","Moreover, audience members are not allowed to make an audio or visual recording of the performance."],"part":7}]},{"set":"161-164","part":7,"type":"e-mail","passages":[{"label":"e-mail","text":"To: Camille Ayala <ayala@esplinelectronics.com>\nFrom: Masae Adachi <madachi@sweeterspecialties.com>\nDate: February 12\nSubject: Event order\nAttachment: Sweeter Specialties Request Form\n\nDear Ms. Ayala,\n\nThank you for selecting our business to provide baked goods for the Esplin Electronics conference event in March. We are honored that you chose us for a fourth year in a row! On March 29, we will provide a large vanilla cake for each of the ten venues you indicated, and we will deliver a custom-baked multilayer cake on the following day. You will be billed on March 28. Please review the attached order form and return it to me within seven days.\n\nRegarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications. In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling. We have judged it to be a delectable treat, and we are sure that you will be pleased.\n\nIf you have any concerns, just send me an e-mail. As always, we value your business.\n\nMasae Adachi, Owner\nSweeter Specialties","text_th":"ถึง: Camille Ayala <ayala@esplinelectronics.com>\nจาก: Masae Adachi <madachi@sweeterspecialties.com>\nวันที่: 12 กุมภาพันธ์\nเรื่อง: คำสั่งซื้อสำหรับงาน\nไฟล์แนบ: แบบฟอร์มคำขอของ Sweeter Specialties\n\nเรียน คุณ Ayala\n\nขอบคุณที่เลือกร้านของเราให้จัดหาขนมอบสำหรับงานประชุมของ Esplin Electronics ในเดือนมีนาคม เรารู้สึกเป็นเกียรติที่คุณเลือกเราเป็นปีที่สี่ติดต่อกัน! ในวันที่ 29 มีนาคม เราจะจัดเตรียมเค้กวานิลลาขนาดใหญ่สำหรับสถานที่จัดงานทั้งสิบแห่งที่คุณระบุไว้ แห่งละหนึ่งก้อน และในวันถัดไปเราจะส่งเค้กหลายชั้นที่อบตามสั่ง คุณจะได้รับใบแจ้งหนี้ในวันที่ 28 มีนาคม โปรดตรวจสอบแบบฟอร์มคำสั่งซื้อที่แนบมาและส่งกลับมาให้ดิฉันภายในเจ็ดวัน\n\nสำหรับเค้กที่คุณสั่งไว้สำหรับวันที่ 30 มีนาคม หัวหน้าเชฟขนมของเราจะทำตามรายละเอียดที่คุณกำหนด อันที่จริง เมื่อเช้านี้เขาได้ทำตัวอย่างตามสูตรที่สมบูรณ์แล้ว เป็นเค้กครีมอัลมอนด์สอดไส้ราสป์เบอร์รีสด เราลงความเห็นว่าเป็นขนมที่อร่อยมาก และมั่นใจว่าคุณจะพอใจ\n\nหากมีข้อกังวลใด ๆ ส่งอีเมลมาหาดิฉันได้เลย เราให้ความสำคัญกับธุรกิจของคุณเสมอ\n\nMasae Adachi เจ้าของร้าน\nSweeter Specialties"}],"vocab":[["honored","รู้สึกเป็นเกียรติ"],["in a row","ติดต่อกัน"],["venue","สถานที่จัดงาน"],["multilayer","หลายชั้น"],["bill","เรียกเก็บเงิน, ส่งใบแจ้งหนี้"],["head","หัวหน้า"],["pastry chef","เชฟขนมอบ"],["specification","รายละเอียดที่กำหนด"],["filling","ไส้ (ขนม)"],["judge","ตัดสิน, ลงความเห็น"],["delectable","อร่อยมาก"],["value","ให้ความสำคัญ"],["confirmation","การยืนยัน"],["adjust","ปรับ"],["expansion","การขยาย"],["annually","ทุกปี"],["combination","การผสมผสาน"]],"questions":[{"n":161,"question":"What is the main purpose of the e-mail?","question_th":"จุดประสงค์หลักของอีเมลนี้คืออะไร","type":"main","options":{"A":"To request confirmation of an order","B":"To adjust some delivery dates","C":"To announce the expansion of a business","D":"To promote new dessert products"},"options_th":{"A":"เพื่อขอให้ยืนยันคำสั่งซื้อ","B":"เพื่อปรับวันส่งของบางวัน","C":"เพื่อประกาศการขยายธุรกิจ","D":"เพื่อโปรโมตขนมหวานใหม่"},"answer":"A","category":"Topic/Purpose","category_th":"หัวข้อ/จุดประสงค์","explain_th":"ประโยคสุดท้ายของย่อหน้าแรกขอให้ตรวจสอบแบบฟอร์มคำสั่งซื้อที่แนบมาแล้วส่งกลับภายในเจ็ดวัน จึงเป็นอีเมลที่ขอให้ยืนยันรายการสั่งซื้อ → (A)","evidence_quotes":["Please review the attached order form and return it to me within seven days."],"part":7},{"n":162,"question":"What is suggested about Ms. Ayala?","question_th":"ข้อใดบอกเป็นนัยเกี่ยวกับคุณ Ayala","type":"inference","options":{"A":"She is receiving a professional award.","B":"She has worked as a pastry chef.","C":"She has been a Sweeter Specialties client in the past.","D":"She received a positive recommendation about a chef."},"options_th":{"A":"เธอกำลังจะได้รับรางวัลทางวิชาชีพ","B":"เธอเคยทำงานเป็นเชฟขนม","C":"เธอเคยเป็นลูกค้าของ Sweeter Specialties มาก่อน","D":"เธอได้รับคำแนะนำในทางบวกเกี่ยวกับเชฟคนหนึ่ง"},"answer":"C","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"ประโยคที่สองบอกว่ารู้สึกเป็นเกียรติที่คุณ Ayala เลือกร้านเป็นปีที่สี่ติดต่อกัน จึงรู้ได้ว่าเธอเป็นลูกค้าเดิมของ Sweeter Specialties → (C)","evidence_quotes":["We are honored that you chose us for a fourth year in a row!"],"part":7},{"n":163,"question":"What is indicated about the multilayer cake?","question_th":"ข้อใดบอกเป็นนัยเกี่ยวกับเค้กหลายชั้น","type":"inference","options":{"A":"It has been a best-selling product with clients.","B":"It is the most expensive cake at Sweeter Specialties.","C":"It is baked for Esplin Electronics annually.","D":"It is a new flavor combination for Sweeter Specialties."},"options_th":{"A":"เป็นสินค้าขายดีที่สุดในหมู่ลูกค้า","B":"เป็นเค้กที่แพงที่สุดของ Sweeter Specialties","C":"อบให้ Esplin Electronics ทุกปี","D":"เป็นการผสมรสชาติใหม่ของ Sweeter Specialties"},"answer":"D","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"ย่อหน้าแรกบอกว่าจะส่งเค้กหลายชั้นที่อบตามสั่งในวันถัดจาก 29 มี.ค. (คือ 30 มี.ค.) ย่อหน้าที่สองบอกว่าเค้กสำหรับ 30 มี.ค. หัวหน้าเชฟจะทำตามที่สั่ง และเมื่อเช้าเพิ่งทำตัวอย่างสูตรสมบูรณ์ (เค้กครีมอัลมอนด์ไส้ราสป์เบอร์รี) จึงอนุมานได้ว่าเป็นรสชาติใหม่ที่ร้านเพิ่งลองทำ → (D)","evidence_quotes":["On March 29, we will provide a large vanilla cake for each of the ten venues you indicated, and we will deliver a custom-baked multilayer cake on the following day.","Regarding the cake you ordered for March 30, our head pastry chef will produce it according to your specifications.","In fact, he created a sample of the complete recipe earlier today—almond crème cake with fresh raspberry filling."],"part":7},{"n":164,"question":"The word “judged” in paragraph 2, line 3, is closest in meaning to","question_th":"คำว่า “judged” ในย่อหน้าที่ 2 บรรทัดที่ 3 มีความหมายใกล้เคียงกับคำใดมากที่สุด","type":"synonym","options":{"A":"criticized","B":"settled","C":"determined","D":"described"},"options_th":{"A":"วิจารณ์","B":"ยุติ, ตกลง","C":"ตัดสิน, ลงความเห็น","D":"บรรยาย"},"answer":"C","category":"Synonym","category_th":"คำที่มีความหมายใกล้เคียง","explain_th":"ในบริบท 'ลงความเห็น/ตัดสินว่าเค้กที่ทำใหม่จะเป็นขนมที่อร่อย' judged ใช้ในความหมาย 'ตัดสิน, ลงความเห็น' → (C) determined","evidence_quotes":["We have judged it to be a delectable treat"],"part":7}]},{"set":"165-167","part":7,"type":"product review","passages":[{"label":"product review","text":"Great Dishwasher!\n\nI never had a dishwasher before. After remodeling my kitchen, I finally had room for a compact dishwasher. I did a lot of research, and the Dish Magic 300 seemed to be the best choice. It was pricier than other models, but all of the reviews were excellent. So, I decided to spend the extra money. I have had the dishwasher for one month now, and I could not be happier with my decision. Most importantly, the dishes come out sparkling clean, no matter how dirty they were going in. Also, the machine is so quiet, you do not even know it is running. Lastly, it is designed to use water efficiently, which is very important to me. Overall, I am very pleased with this dishwasher.\n\n– Anna Yakovleva","text_th":"เครื่องล้างจานยอดเยี่ยม!\n\nฉันไม่เคยมีเครื่องล้างจานมาก่อน หลังจากปรับปรุงห้องครัว ในที่สุดฉันก็มีพื้นที่พอสำหรับเครื่องล้างจานขนาดกะทัดรัด ฉันหาข้อมูลมากมาย และ Dish Magic 300 ดูจะเป็นตัวเลือกที่ดีที่สุด ราคาแพงกว่ารุ่นอื่น แต่รีวิวทั้งหมดดีเยี่ยม ฉันจึงตัดสินใจจ่ายเงินเพิ่ม ตอนนี้ฉันใช้เครื่องมาได้หนึ่งเดือนแล้ว และพอใจกับการตัดสินใจครั้งนี้มากที่สุด ที่สำคัญที่สุดคือ จานออกมาสะอาดเป็นประกาย ไม่ว่าตอนใส่เข้าไปจะสกปรกแค่ไหน นอกจากนี้เครื่องยังเงียบมากจนไม่รู้ด้วยซ้ำว่ากำลังทำงานอยู่ สุดท้าย เครื่องถูกออกแบบมาให้ใช้น้ำอย่างมีประสิทธิภาพ ซึ่งสำคัญกับฉันมาก โดยรวมแล้วฉันพอใจกับเครื่องล้างจานนี้มาก\n\n– Anna Yakovleva"}],"vocab":[["room","พื้นที่ว่าง"],["compact","ขนาดกะทัดรัด"],["pricey","ราคาแพง"],["sparkling","เป็นประกาย, สะอาดวิ้ง"],["no matter how","ไม่ว่า…แค่ไหน"],["efficiently","อย่างมีประสิทธิภาพ"],["overall","โดยรวม"],["rate","ให้คะแนน, ประเมิน"],["appliance","เครื่องใช้ไฟฟ้า"]],"questions":[{"n":165,"question":"Why did Ms. Yakovleva choose the Dish Magic 300 dishwasher?","question_th":"ทำไมคุณ Yakovleva จึงเลือกเครื่องล้างจาน Dish Magic 300","type":"detail","options":{"A":"It was less expensive than most models.","B":"It was the largest model available.","C":"It was rated very highly.","D":"It was the same brand as her other appliances."},"options_th":{"A":"ราคาถูกกว่ารุ่นส่วนใหญ่","B":"เป็นรุ่นที่ใหญ่ที่สุดที่มีขาย","C":"ได้รับคะแนนรีวิวสูงมาก","D":"เป็นยี่ห้อเดียวกับเครื่องใช้ไฟฟ้าอื่นของเธอ"},"answer":"C","category":"Detail","category_th":"รายละเอียด","explain_th":"ประโยคที่สามบอกว่าหาข้อมูลมากและ Dish Magic 300 ดูดีที่สุด และประโยคถัดมาบอกว่าแพงกว่ารุ่นอื่นแต่รีวิวดีเยี่ยมทั้งหมด → (C)","evidence_quotes":["I did a lot of research, and the Dish Magic 300 seemed to be the best choice.","It was pricier than other models, but all of the reviews were excellent."],"paraphrase":[["all of the reviews were excellent","It was rated very highly"]],"part":7},{"n":166,"question":"The word “running” in paragraph 1, line 7, is closest in meaning to","question_th":"คำว่า “running” ในย่อหน้าที่ 1 บรรทัดที่ 7 มีความหมายใกล้เคียงกับคำใดมากที่สุด","type":"synonym","options":{"A":"adjusting","B":"controlling","C":"moving","D":"operating"},"options_th":{"A":"กำลังปรับ","B":"กำลังควบคุม","C":"กำลังเคลื่อนที่","D":"กำลังทำงาน"},"answer":"D","category":"Synonym","category_th":"คำที่มีความหมายใกล้เคียง","explain_th":"ในบริบท 'เครื่องเงียบจนไม่รู้ว่ากำลังทำงานอยู่' running หมายถึง 'กำลังทำงาน' → (D) operating","evidence_quotes":["the machine is so quiet, you do not even know it is running"],"part":7},{"n":167,"question":"What is indicated about Ms. Yakovleva?","question_th":"ข้อใดกล่าวถึงคุณ Yakovleva ได้ถูกต้อง","type":"not-true","options":{"A":"She cares about saving water.","B":"She recently moved to a new home.","C":"She bought the dishwasher a year ago.","D":"She remodels kitchens professionally."},"options_th":{"A":"เธอใส่ใจเรื่องการประหยัดน้ำ","B":"เธอเพิ่งย้ายบ้านใหม่","C":"เธอซื้อเครื่องล้างจานเมื่อหนึ่งปีก่อน","D":"เธอรับปรับปรุงห้องครัวเป็นอาชีพ"},"answer":"A","category":"Not/True","category_th":"Not/True (ข้อใดถูก/ไม่ถูก)","explain_th":"ประโยคที่เก้าบอกว่าเครื่องออกแบบมาให้ใช้น้ำอย่างมีประสิทธิภาพ ซึ่งสำคัญกับเธอมาก แสดงว่าเธอใส่ใจเรื่องประหยัดน้ำ → (A)","evidence_quotes":["Lastly, it is designed to use water efficiently, which is very important to me."],"paraphrase":[["use water efficiently","saving water"]],"part":7}]},{"set":"168-171","part":7,"type":"information","passages":[{"label":"information","text":"Skyler Airlines employs more than 20,000 people from all over the world. We’re growing fast and have many positions available. — [1] —. So regardless of your background, there’s probably a place for you on our team. Skyler employees enjoy many perks. — [2] —. For example, our discount program enables them to fly to any of our destinations for a fraction of the average ticket price. — [3] —. We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package. — [4] —. Annual paid vacations enable a comfortable work-life balance. It’s no wonder that Skyler Airlines was named “Best Airline to Work For” by Travel Vista Journal three years in a row.","text_th":"Skyler Airlines มีพนักงานมากกว่า 20,000 คนจากทั่วโลก เรากำลังเติบโตอย่างรวดเร็วและมีตำแหน่งงานว่างมากมาย — [1] — ดังนั้นไม่ว่าคุณจะมีพื้นฐานแบบใด ก็น่าจะมีที่สำหรับคุณในทีมของเรา พนักงานของ Skyler ได้รับสวัสดิการมากมาย — [2] — ตัวอย่างเช่น โครงการส่วนลดของเราช่วยให้พนักงานบินไปจุดหมายใดก็ได้ของเราโดยจ่ายเพียงเศษเสี้ยวของราคาตั๋วเฉลี่ย — [3] — เรามีโอกาสความก้าวหน้าในสายงานและการโยกย้ายไปทำงานทั่วโลก การคืนเงินค่าเล่าเรียน โครงการพี่เลี้ยง และค่าตอบแทนที่ดีมาก — [4] — วันหยุดพักร้อนประจำปีแบบได้รับค่าจ้างช่วยให้สมดุลระหว่างงานกับชีวิตส่วนตัวเป็นไปอย่างสบาย ๆ ไม่น่าแปลกใจเลยที่ Skyler Airlines ได้รับการยกย่องให้เป็น “สายการบินที่น่าทำงานด้วยมากที่สุด” จากนิตยสาร Travel Vista Journal สามปีติดต่อกัน"}],"vocab":[["employ","จ้างงาน"],["regardless of","ไม่ว่า…, โดยไม่คำนึงถึง"],["background","พื้นฐาน (การศึกษา/ประสบการณ์)"],["perk","สวัสดิการพิเศษ"],["enable","ทำให้สามารถ"],["destination","จุดหมายปลายทาง"],["fraction","ส่วนเล็ก ๆ, เศษเสี้ยว"],["average","เฉลี่ย"],["upward mobility","โอกาสเลื่อนตำแหน่ง/ความก้าวหน้า"],["tuition","ค่าเล่าเรียน"],["reimbursement","การคืนเงิน"],["generous","ใจกว้าง, มาก"],["compensation","ค่าตอบแทน"],["paid vacation","วันหยุดพักร้อนแบบได้รับค่าจ้าง"],["in a row","ติดต่อกัน"],["potential","ที่มีแนวโน้มจะเป็น"],["subscriber","สมาชิกผู้รับ (นิตยสาร)"],["job seeker","ผู้หางาน"],["educational","เกี่ยวกับการศึกษา"],["expense","ค่าใช้จ่าย"],["opportunity","โอกาส"],["merge","ควบรวม"],["praise","ชื่นชม"],["trade","ธุรกิจ, วงการค้า"],["opening","ตำแหน่งงานว่าง"],["cover","ครอบคลุม"],["skill set","ชุดทักษะ"]],"questions":[{"n":168,"question":"For whom is the information intended?","question_th":"ข้อมูลนี้มีไว้สำหรับใคร","type":"inference","options":{"A":"Skyler Airlines employees","B":"Skyler Airlines customers","C":"Potential journal subscribers","D":"Current job seekers"},"options_th":{"A":"พนักงานของ Skyler Airlines","B":"ลูกค้าของ Skyler Airlines","C":"ผู้ที่อาจเป็นสมาชิกนิตยสาร","D":"ผู้ที่กำลังหางาน"},"answer":"D","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"ประโยคที่สองบอกว่าบริษัทเติบโตเร็วและมีตำแหน่งว่างมาก แล้วบอกว่าไม่ว่าคุณจะมีพื้นฐานแบบใดก็น่าจะมีที่ในทีม จึงเป็นข้อมูลสำหรับผู้หางาน → (D)","evidence_quotes":["We’re growing fast and have many positions available.","So regardless of your background, there’s probably a place for you on our team."],"part":7},{"n":169,"question":"In the information, what is NOT mentioned as being offered to employees?","question_th":"ข้อใดไม่ได้กล่าวถึงว่าเป็นสิ่งที่บริษัทให้แก่พนักงาน","type":"not-true","options":{"A":"Payment for educational expenses","B":"Free airline tickets","C":"Opportunities for mentoring","D":"Paid days off"},"options_th":{"A":"การจ่ายค่าใช้จ่ายด้านการศึกษา","B":"ตั๋วเครื่องบินฟรี","C":"โอกาสในการมีพี่เลี้ยง","D":"วันหยุดแบบได้รับค่าจ้าง"},"answer":"B","category":"Not/True","category_th":"Not/True (ข้อใดถูก/ไม่ถูก)","explain_th":"ประโยคที่เจ็ดกล่าวถึงการคืนเงินค่าเล่าเรียน (A) และโครงการพี่เลี้ยง (C) ประโยคถัดไปกล่าวถึงวันหยุดพักร้อนแบบได้รับค่าจ้าง (D) ส่วนประโยคที่หกบอกว่าโครงการส่วนลดให้บินโดยจ่ายเพียงส่วนหนึ่งของราคาตั๋วเฉลี่ย แสดงว่าตั๋วไม่ได้ฟรีแต่ได้ส่วนลด → (B)","evidence_quotes":["For example, our discount program enables them to fly to any of our destinations for a fraction of the average ticket price.","We offer upward and global mobility, tuition reimbursement, a mentorship program, and a generous compensation package.","Annual paid vacations enable a comfortable work-life balance."],"paraphrase":[["tuition reimbursement","Payment for educational expenses"],["mentorship program","Opportunities for mentoring"],["paid vacations","Paid days off"]],"part":7},{"n":170,"question":"What is mentioned about Skyler Airlines?","question_th":"ข้อใดกล่าวถึง Skyler Airlines","type":"not-true","options":{"A":"It flies to the most destinations around the world.","B":"It is planning to merge with another airline.","C":"It has been praised by a trade publication.","D":"It has replaced its seats with more comfortable ones."},"options_th":{"A":"บินไปยังจุดหมายมากที่สุดในโลก","B":"กำลังวางแผนควบรวมกับสายการบินอื่น","C":"ได้รับคำชมจากสิ่งพิมพ์ในวงการ","D":"เปลี่ยนที่นั่งเป็นแบบที่สบายขึ้น"},"answer":"C","category":"Not/True","category_th":"Not/True (ข้อใดถูก/ไม่ถูก)","explain_th":"ประโยคสุดท้ายบอกว่า Skyler Airlines ได้รับเลือกเป็น 'สายการบินที่น่าทำงานด้วยที่สุด' จาก Travel Vista Journal สามปีติดต่อกัน คือได้รับคำชมจากสิ่งพิมพ์ในวงการ → (C)","evidence_quotes":["It’s no wonder that Skyler Airlines was named “Best Airline to Work For” by Travel Vista Journal three years in a row."],"part":7},{"n":171,"question":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n“Our openings cover a broad range of skill sets.”","question_th":"ประโยคต่อไปนี้ควรอยู่ในตำแหน่งใดมากที่สุดในบรรดา [1] [2] [3] และ [4]\n“ตำแหน่งงานว่างของเราครอบคลุมทักษะหลากหลายด้าน”","type":"insert","options":{"A":"[1]","B":"[2]","C":"[3]","D":"[4]"},"options_th":{"A":"[1]","B":"[2]","C":"[3]","D":"[4]"},"answer":"A","category":"Sentence insertion","category_th":"การแทรกประโยค","explain_th":"ประโยคที่ให้มาพูดถึงตำแหน่งงานที่ครอบคลุมทักษะหลากหลาย จึงควรอยู่ระหว่าง 'มีตำแหน่งว่างมาก' กับ 'ไม่ว่าพื้นฐานแบบใดก็มีที่ให้คุณ' ซึ่งเน้นโอกาสงานที่หลากหลาย → [1] (A)","evidence_quotes":["We’re growing fast and have many positions available.","So regardless of your background, there’s probably a place for you on our team."],"part":7}]},{"set":"172-175","part":7,"type":"online chat","passages":[{"label":"online chat discussion","text":"Susan Gowan (9:16 A.M.): Good morning. The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores. We are on track to send them out next Monday.\nMaggie Lorenz (9:17 A.M.): How do they look?\nSusan Gowan (9:20 A.M.): There are still some missing elements.\nAlan Woodson (9:21 A.M.): We mainly need the information from the user studies that reviewed the headphones for sport use. We should have that report from the research and development office by Wednesday.\nMaggie Lorenz (9:22 A.M.): Yes, let’s not overlook that. And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us.\nSusan Gowan (9:23 A.M.): Assuming we receive that summary soon enough to incorporate its findings into the slides, should the three of us schedule a trial run through the presentation on Thursday or Friday?\nMaggie Lorenz (9:24 A.M.): Let’s try for Thursday afternoon. Then we will still have Friday to make any necessary changes.\nAlan Woodson (9:25 A.M.): Fine by me. I’m free after 2 P.M.","text_th":"Susan Gowan (9:16 น.): อรุณสวัสดิ์ค่ะ สไลด์นำเสนอหูฟังรุ่นใหม่เกือบพร้อมส่งให้ร้านค้าพันธมิตรหลายแห่งของเราแล้ว เรายังเป็นไปตามแผนที่จะส่งออกไปวันจันทร์หน้า\nMaggie Lorenz (9:17 น.): สไลด์เป็นอย่างไรบ้าง\nSusan Gowan (9:20 น.): ยังขาดองค์ประกอบบางส่วนอยู่ค่ะ\nAlan Woodson (9:21 น.): หลัก ๆ เราต้องการข้อมูลจากการศึกษาผู้ใช้ที่ทดสอบหูฟังสำหรับใช้เล่นกีฬา เราน่าจะได้รายงานนั้นจากฝ่ายวิจัยและพัฒนาภายในวันพุธ\nMaggie Lorenz (9:22 น.): ใช่ อย่ามองข้ามเรื่องนั้นนะ และถ้ากังวลว่ารายงานจะมาไม่ทันวันพุธ ให้ติดต่อ Matt Harven และเตือนเขาให้เร่งส่งสรุปมาให้เรา\nSusan Gowan (9:23 น.): สมมุติว่าเราได้รับสรุปเร็วพอที่จะใส่ผลการศึกษาลงในสไลด์ได้ เราสามคนควรนัดซ้อมนำเสนอกันวันพฤหัสบดีหรือวันศุกร์ดีคะ\nMaggie Lorenz (9:24 น.): ลองเป็นบ่ายวันพฤหัสบดีกัน แล้วเราจะยังมีวันศุกร์ไว้แก้ไขสิ่งที่จำเป็น\nAlan Woodson (9:25 น.): ผมโอเคครับ ผมว่างหลังบ่ายสองโมง"}],"vocab":[["distribution","การแจกจ่าย"],["be on track","เป็นไปตามแผน"],["missing","ที่ขาดหายไป"],["element","องค์ประกอบ"],["overlook","มองข้าม"],["expedite","เร่งดำเนินการ"],["summary","บทสรุป"],["assuming","สมมุติว่า"],["incorporate","รวมเข้าไป, ใส่"],["findings","ผลการศึกษา"],["trial run","การซ้อม, การทดลองทำ"],["highlight","เน้น"],["multiple","หลาย"],["smoothly","อย่างราบรื่น"],["notify","แจ้ง"],["upcoming","ที่กำลังจะมา"],["athlete","นักกีฬา"],["executive","ผู้บริหาร"]],"questions":[{"n":172,"question":"What is indicated about a presentation?","question_th":"ข้อใดกล่าวถึงการนำเสนอได้ถูกต้อง","type":"not-true","options":{"A":"It will be expensive to produce.","B":"It will highlight some best-selling products.","C":"It will be Ms. Gowan’s first project.","D":"It will be sent to multiple locations."},"options_th":{"A":"จะมีค่าใช้จ่ายในการทำสูง","B":"จะเน้นสินค้าขายดีบางรายการ","C":"จะเป็นโปรเจกต์แรกของคุณ Gowan","D":"จะถูกส่งไปหลายสถานที่"},"answer":"D","category":"Not/True","category_th":"Not/True (ข้อใดถูก/ไม่ถูก)","explain_th":"9:16 Gowan บอกว่าสไลด์นำเสนอหูฟังรุ่นใหม่เกือบพร้อมจะส่งให้ร้านค้าพันธมิตรหลายแห่ง แสดงว่าจะถูกส่งไปหลายที่ → (D)","evidence_quotes":["The presentation slides about the new line of headphones are almost ready for distribution to our many partner stores."],"paraphrase":[["our many partner stores","multiple locations"]],"part":7},{"n":173,"question":"At 9:22 A.M., what does Ms. Lorenz imply when she writes, “let’s not overlook that”?","question_th":"เวลา 9:22 น. คุณ Lorenz สื่อเป็นนัยว่าอะไรเมื่อเขียนว่า “let’s not overlook that”","type":"intent","options":{"A":"More staff should attend a meeting.","B":"Information from the user studies is important.","C":"The presentation must run smoothly.","D":"Partner stores must be notified about an upcoming report."},"options_th":{"A":"ควรมีพนักงานเข้าประชุมมากขึ้น","B":"ข้อมูลจากการศึกษาผู้ใช้มีความสำคัญ","C":"การนำเสนอต้องดำเนินไปอย่างราบรื่น","D":"ต้องแจ้งร้านค้าพันธมิตรเรื่องรายงานที่จะออกมา"},"answer":"B","category":"Writer’s intent","category_th":"เจตนาของผู้เขียน","explain_th":"9:21 Woodson บอกว่าต้องการข้อมูลจากการศึกษาผู้ใช้หูฟังสำหรับกีฬาเป็นหลัก และควรได้รายงานจากฝ่าย R&D ภายในวันพุธ Lorenz ตอบว่า 'อย่ามองข้ามเรื่องนั้น' จึงเป็นการเน้นว่าข้อมูลการศึกษาผู้ใช้สำคัญ → (B)","evidence_quotes":["We mainly need the information from the user studies that reviewed the headphones for sport use.","We should have that report from the research and development office by Wednesday."],"part":7},{"n":174,"question":"Who most likely is Mr. Harven?","question_th":"คุณ Harven น่าจะเป็นใคร","type":"inference","options":{"A":"A store manager","B":"An amateur athlete","C":"A product researcher","D":"An advertising executive"},"options_th":{"A":"ผู้จัดการร้าน","B":"นักกีฬาสมัครเล่น","C":"นักวิจัยผลิตภัณฑ์","D":"ผู้บริหารฝ่ายโฆษณา"},"answer":"C","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"9:21 Woodson บอกว่าควรได้รายงานจากฝ่ายวิจัยและพัฒนาภายในวันพุธ 9:22 Lorenz บอกว่าถ้ากังวลว่ารายงานจะไม่ทัน ให้ติดต่อ Matt Harven ให้เร่งส่งสรุปมา จึงอนุมานได้ว่า Harven ทำงานในฝ่ายวิจัยและพัฒนา → (C)","evidence_quotes":["We should have that report from the research and development office by Wednesday.","And if you're concerned about the report not arriving by Wednesday, please contact Matt Harven and remind him to expedite a summary to us."],"part":7},{"n":175,"question":"When do the writers plan to meet to review a slide presentation?","question_th":"ผู้เขียนวางแผนจะพบกันเพื่อทบทวนสไลด์นำเสนอเมื่อไร","type":"detail","options":{"A":"On Monday","B":"On Wednesday","C":"On Thursday","D":"On Friday"},"options_th":{"A":"วันจันทร์","B":"วันพุธ","C":"วันพฤหัสบดี","D":"วันศุกร์"},"answer":"C","category":"Detail","category_th":"รายละเอียด","explain_th":"9:23 Gowan ถามว่าทั้งสามควรนัดซ้อมนำเสนอวันพฤหัสหรือศุกร์ 9:24 Lorenz ตอบว่าบ่ายวันพฤหัส → (C)","evidence_quotes":["should the three of us schedule a trial run through the presentation on Thursday or Friday?","Let’s try for Thursday afternoon."],"part":7}]},{"set":"176-180","part":7,"type":"press release + review","passages":[{"label":"press release","text":"Aparna Kothari, Media Contact\nKitchen Swifts\nakothari@kitchenswifts.com.au\n\nFOR IMMEDIATE RELEASE\n\nSYDNEY (4 June)—Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience. The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua’s. He says his cooking reflects his Filipino heritage, which is a blend of many cultures.\n\n“I’ve designed these simplified recipes for Kitchen Swifts so that cooks at home can enjoy new and exciting flavours with ease,” he said. “While preparing and eating these meals, you can feel like you are travelling the world with me.”\n\nZahra Chambers, vice president of Kitchen Swifts, says she is pleased to work with Chef Cordero and to offer delicious new recipes to their customers. Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections. Customers choose the most appropriate meal options, and then a box is delivered weekly. Current customers will see no price increase with the partnership. To find out more, visit the Kitchen Swifts Web site at www.kitchenswifts.com.au.","text_th":"Aparna Kothari ผู้ประสานงานสื่อ\nKitchen Swifts\nakothari@kitchenswifts.com.au\n\nเผยแพร่ทันที\n\nSYDNEY (4 มิถุนายน) — Kitchen Swifts และเชฟ Darius Cordero ร่วมมือกันมอบประสบการณ์การทำอาหารแบบใหม่ให้แก่ผู้ที่ทำอาหารที่บ้าน เชฟผู้ได้รับรางวัลท่านนี้เป็นเจ้าของร้านอาหารทั้งในฟิลิปปินส์และออสเตรเลีย รวมถึงร้าน Enriqua’s ที่เพิ่งเปิดไม่นานนี้ เขากล่าวว่าอาหารของเขาสะท้อนมรดกทางวัฒนธรรมแบบฟิลิปปินส์ ซึ่งเป็นการผสมผสานของหลายวัฒนธรรม\n\n“ผมออกแบบสูตรอาหารแบบง่ายเหล่านี้ให้ Kitchen Swifts เพื่อให้คนที่ทำอาหารที่บ้านได้เพลิดเพลินกับรสชาติใหม่ ๆ ที่น่าตื่นเต้นได้อย่างง่ายดาย” เขากล่าว “ระหว่างที่เตรียมและรับประทานอาหารเหล่านี้ คุณจะรู้สึกเหมือนได้เดินทางรอบโลกไปกับผม”\n\nZahra Chambers รองประธานของ Kitchen Swifts กล่าวว่ายินดีที่ได้ร่วมงานกับเชฟ Cordero และได้นำเสนอสูตรอาหารใหม่แสนอร่อยให้ลูกค้า Kitchen Swifts จัดหาเมนู สูตรอาหาร และวัตถุดิบสำหรับ 2 คน 4 คน หรือ 6 คน รวมถึงตัวเลือกมังสวิรัติหลากหลาย ลูกค้าเลือกเมนูที่เหมาะสมที่สุด แล้วจะได้รับกล่องอาหารจัดส่งทุกสัปดาห์ ลูกค้าปัจจุบันจะไม่ต้องจ่ายแพงขึ้นจากความร่วมมือครั้งนี้ ดูข้อมูลเพิ่มเติมได้ที่เว็บไซต์ Kitchen Swifts www.kitchenswifts.com.au"},{"label":"review","text":"https://www.sydneyrestaurants.com.au\n\nA colleague arranged for us to eat at Enriqua’s while I was at a conference in Sydney. It is usually fully booked for dinner; you may need to call months in advance for a table. We had a wonderful lunch there instead. Everything was delicious, and the bread and desserts are baked on-site! It was a worthwhile treat before I flew back to Hong Kong.\n\n—Meili Guan","text_th":"https://www.sydneyrestaurants.com.au\n\nเพื่อนร่วมงานจัดการให้พวกเราได้ไปทานอาหารที่ Enriqua’s ระหว่างที่ฉันมาร่วมประชุมที่ซิดนีย์ ปกติร้านนี้มื้อค่ำจะเต็มตลอด อาจต้องโทรจองโต๊ะล่วงหน้าเป็นเดือน ๆ พวกเราจึงไปทานมื้อกลางวันที่นั่นแทน ซึ่งยอดเยี่ยมมาก ทุกอย่างอร่อย และขนมปังกับของหวานก็อบกันที่ร้านเลย! เป็นมื้อพิเศษที่คุ้มค่าก่อนที่ฉันจะบินกลับฮ่องกง\n\n—Meili Guan","image":"img/rc_t01_176-180_2.png"}],"vocab":[["immediate","ทันที"],["release","การเผยแพร่ (ข่าว)"],["culinary","เกี่ยวกับการทำอาหาร"],["reflect","สะท้อน"],["Filipino","แบบฟิลิปปินส์"],["heritage","มรดกทางวัฒนธรรม"],["blend","การผสมผสาน"],["simplified","ที่ทำให้ง่ายขึ้น"],["flavour","รสชาติ"],["with ease","อย่างง่ายดาย"],["vice president","รองประธาน"],["ingredient","วัตถุดิบ"],["selection","ตัวเลือก"],["appropriate","เหมาะสม"],["recipient","ผู้รับ"],["raise","ขึ้น (ราคา)"],["revise","แก้ไข, ปรับเปลี่ยน"],["colleague","เพื่อนร่วมงาน"],["arrange","จัดการ, เตรียมการ"],["fully booked","ถูกจองเต็ม"],["in advance","ล่วงหน้า"],["on-site","ในสถานที่"],["worthwhile","คุ้มค่า"],["treat","สิ่งพิเศษ, การเลี้ยง"],["serve","เสิร์ฟ (อาหาร)"]],"questions":[{"n":176,"question":"What is the purpose of the press release?","question_th":"จุดประสงค์ของข่าวประชาสัมพันธ์คืออะไร","type":"main","options":{"A":"To promote the opening of a restaurant","B":"To announce a business partnership","C":"To introduce a travel program","D":"To congratulate an award recipient"},"options_th":{"A":"เพื่อโปรโมตการเปิดร้านอาหาร","B":"เพื่อประกาศความร่วมมือทางธุรกิจ","C":"เพื่อแนะนำโครงการท่องเที่ยว","D":"เพื่อแสดงความยินดีกับผู้ได้รับรางวัล"},"answer":"B","category":"Topic/Purpose","category_th":"หัวข้อ/จุดประสงค์","explain_th":"ประโยคแรกของข่าวบอกว่า Kitchen Swifts กับเชฟ Darius Cordero ร่วมมือกันมอบประสบการณ์ทำอาหารใหม่ให้คนทำอาหารที่บ้าน จึงเป็นข่าวประกาศความร่วมมือระหว่างสองฝ่าย → (B)","evidence_quotes":["Kitchen Swifts and Chef Darius Cordero are joining together to give home cooks a new culinary experience."],"part":7},{"n":177,"question":"In the press release, the word “reflects” in paragraph 1, line 4, is closest in meaning to","question_th":"ในข่าวประชาสัมพันธ์ คำว่า “reflects” ในย่อหน้าที่ 1 บรรทัดที่ 4 มีความหมายใกล้เคียงกับคำใดมากที่สุด","type":"synonym","options":{"A":"results in","B":"changes","C":"shows","D":"thinks about"},"options_th":{"A":"ส่งผลให้เกิด","B":"เปลี่ยน","C":"แสดงให้เห็น","D":"คิดถึง"},"answer":"C","category":"Synonym","category_th":"คำที่มีความหมายใกล้เคียง","explain_th":"ในบริบท 'อาหารของเขาสะท้อนมรดกวัฒนธรรมฟิลิปปินส์' reflects หมายถึง 'แสดงให้เห็น' → (C) shows","evidence_quotes":["He says his cooking reflects his Filipino heritage"],"part":7},{"n":178,"question":"What is indicated about Kitchen Swifts?","question_th":"ข้อใดกล่าวถึง Kitchen Swifts ได้ถูกต้อง","type":"not-true","options":{"A":"It raised its prices for all customers.","B":"It revised its delivery schedule.","C":"It offers several meal options.","D":"It has a new vice president."},"options_th":{"A":"ขึ้นราคาสำหรับลูกค้าทุกคน","B":"ปรับตารางการจัดส่งใหม่","C":"มีตัวเลือกมื้ออาหารหลายแบบ","D":"มีรองประธานคนใหม่"},"answer":"C","category":"Not/True","category_th":"Not/True (ข้อใดถูก/ไม่ถูก)","explain_th":"ย่อหน้าที่สามบอกว่า Kitchen Swifts มีเมนู สูตร และวัตถุดิบสำหรับ 2, 4 หรือ 6 คน รวมถึงตัวเลือกมังสวิรัติหลากหลาย → (C) ถูก  ประโยคที่สี่บอกว่าลูกค้าปัจจุบันจะไม่ต้องจ่ายแพงขึ้น ตัด (A) ส่วน (B)(D) ไม่ได้กล่าวถึง","evidence_quotes":["Kitchen Swifts supplies menus, recipes, and ingredients for two people, four people, or six people, including a range of vegetarian selections.","Current customers will see no price increase with the partnership."],"part":7},{"n":179,"question":"What is most likely true about Ms. Guan?","question_th":"ข้อใดน่าจะเป็นจริงเกี่ยวกับคุณ Guan","type":"cross","options":{"A":"She went to Mr. Cordero’s restaurant.","B":"She recently went to Sydney for a vacation.","C":"She is a colleague of Ms. Chambers.","D":"She regularly orders from Kitchen Swifts."},"options_th":{"A":"เธอไปร้านอาหารของคุณ Cordero มา","B":"เธอเพิ่งไปเที่ยวพักผ่อนที่ซิดนีย์","C":"เธอเป็นเพื่อนร่วมงานของคุณ Chambers","D":"เธอสั่งอาหารจาก Kitchen Swifts เป็นประจำ"},"answer":"A","category":"Cross-reference","category_th":"เชื่อมโยงหลายข้อความ","explain_th":"รีวิวประโยคแรกบอกว่าเพื่อนร่วมงานจัดให้ไปกินที่ Enriqua’s ระหว่างที่ไปประชุมที่ซิดนีย์ และข่าวประชาสัมพันธ์ประโยคที่สองบอกว่าเชฟ Cordero เป็นเจ้าของร้านอาหารรวมถึง Enriqua’s ที่เพิ่งเปิด จึงรู้ว่าคุณ Guan ไปร้านของคุณ Cordero → (A)","evidence_quotes":["A colleague arranged for us to eat at Enriqua’s while I was at a conference in Sydney.","The award-winning chef is the owner of restaurants in both the Philippines and Australia, including the recently opened Enriqua’s."],"part":7},{"n":180,"question":"What did Ms. Guan suggest about Enriqua’s in the review?","question_th":"คุณ Guan บอกเป็นนัยอะไรเกี่ยวกับ Enriqua’s ในรีวิว","type":"inference","options":{"A":"It has a limited lunch menu.","B":"It takes dinner reservations.","C":"It serves bread from a local bakery.","D":"It has a location in Hong Kong."},"options_th":{"A":"มีเมนูมื้อกลางวันจำกัด","B":"รับจองโต๊ะสำหรับมื้อค่ำ","C":"เสิร์ฟขนมปังจากร้านเบเกอรีในท้องถิ่น","D":"มีสาขาในฮ่องกง"},"answer":"B","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"รีวิวประโยคที่สองบอกว่ามื้อค่ำมักถูกจองเต็ม อาจต้องโทรจองโต๊ะล่วงหน้าหลายเดือน แสดงว่าร้านรับจองโต๊ะมื้อค่ำ → (B)","evidence_quotes":["It is usually fully booked for dinner; you may need to call months in advance for a table."],"paraphrase":[["call months in advance for a table","takes dinner reservations"]],"part":7}]},{"set":"181-185","part":7,"type":"e-mail + ticket","passages":[{"label":"e-mail","text":"To: laura.savard@orbitmail.scot\nFrom: cboyle@ceoleire.co.uk\nDate: 25 May\nSubject: RE: Some suggestions\n\nDear Ms. Savard,\n\nThank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport. Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself. It so happens that my sister and her children live nearby in Kirkcolm. Before seeing them, I will drive my rental car to your house and hand deliver the items to you.\n\nAs you know, my merchandise is 100 percent handcrafted. If any damage occurs in transit, the repair turns into an expensive, time-consuming ordeal. Over the years, I’ve seen too much damage done by inattentive baggage handlers. My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust.\n\nI look forward to meeting you on 5 June. I expect to arrive at your house no later than 5 p.m.\n\nSincerely,\n\nConor Boyle\nCeoleire Classics","text_th":"ถึง: laura.savard@orbitmail.scot\nจาก: cboyle@ceoleire.co.uk\nวันที่: 25 พฤษภาคม\nเรื่อง: RE: ข้อเสนอบางประการ\n\nเรียน คุณ Savard\n\nขอบคุณสำหรับข้อเสนออันดีที่จะมารับสินค้าที่สั่งออนไลน์ด้วยตัวเองที่ร้านของผม หรือจะจ่ายค่าขนส่งทางอากาศหรือรถไฟเพิ่ม ไม่จำเป็นต้องทำแบบใดเลยครับ เพราะผมยินดีนำสินค้าไปส่งให้คุณที่ Stranraer ด้วยตัวเอง บังเอิญว่าน้องสาวของผมและลูก ๆ ของเธออาศัยอยู่ใกล้ ๆ ที่ Kirkcolm ก่อนไปหาพวกเขา ผมจะขับรถเช่าไปที่บ้านคุณและส่งสินค้าให้ถึงมือ\n\nอย่างที่คุณทราบ สินค้าของผมทำด้วยมือ 100 เปอร์เซ็นต์ หากเกิดความเสียหายระหว่างขนส่ง การซ่อมจะกลายเป็นเรื่องยุ่งยากที่ทั้งแพงและเสียเวลา หลายปีที่ผ่านมา ผมเห็นความเสียหายจากพนักงานขนสัมภาระที่ไม่ระมัดระวังมามากเกินไป นโยบายของผมคือส่งสินค้าด้วยตัวเองทุกครั้งที่ทำได้ หรือไม่ก็จ้างบริการขนส่งทางบกหรือทางทะเลที่ผมไว้ใจ\n\nผมหวังว่าจะได้พบคุณในวันที่ 5 มิถุนายน คาดว่าจะไปถึงบ้านคุณไม่เกิน 5 โมงเย็น\n\nขอแสดงความนับถือ\n\nConor Boyle\nCeoleire Classics"},{"label":"ticket","text":"Northern Ireland Ferry Service\n\nDate of Issuance: | 26 May\nPassenger Name: | Conor Boyle\n\nDeparting Belfast: | Friday, 5 June, 1:05 PM\nDocking at Cairnryan: | Friday, 5 June, 3:20 PM\n\nBaggage: | 1 suitcase (small), 2 instrument cases (1 mandolin, 1 guitar)\nVehicle transport: | No\n\nAdult Standard Class: | £55.00\n\nPlease arrive 30 minutes prior to departure.","text_th":"Northern Ireland Ferry Service (บริการเรือเฟอร์รีไอร์แลนด์เหนือ)\n\nวันที่ออกตั๋ว: | 26 พฤษภาคม\nชื่อผู้โดยสาร: | Conor Boyle\n\nออกจาก Belfast: | วันศุกร์ที่ 5 มิถุนายน 13:05 น.\nเทียบท่าที่ Cairnryan: | วันศุกร์ที่ 5 มิถุนายน 15:20 น.\n\nสัมภาระ: | กระเป๋าเดินทาง 1 ใบ (เล็ก), กล่องเครื่องดนตรี 2 กล่อง (แมนโดลิน 1, กีตาร์ 1)\nขนส่งยานพาหนะ: | ไม่มี\n\nผู้ใหญ่ ชั้นมาตรฐาน: | 55.00 ปอนด์\n\nโปรดมาถึงก่อนเวลาออกเดินทาง 30 นาที","image":"img/rc_t01_181-185_2.png"}],"vocab":[["transport","การขนส่ง"],["arrangement","การจัดเตรียม"],["merchandise","สินค้า"],["handcrafted","ทำด้วยมือ"],["occur","เกิดขึ้น"],["transit","การขนส่ง (ระหว่างทาง)"],["time-consuming","เสียเวลา"],["ordeal","เรื่องยุ่งยาก, ประสบการณ์ที่ลำบาก"],["inattentive","ไม่ใส่ใจ, สะเพร่า"],["baggage","สัมภาระ"],["feasible","เป็นไปได้"],["courier","บริการรับส่งพัสดุ"],["no later than","ไม่เกิน, ภายใน"],["ferry","เรือเฟอร์รี"],["issuance","การออก (ตั๋ว/เอกสาร)"],["passenger","ผู้โดยสาร"],["dock","เทียบท่า"],["instrument","เครื่องดนตรี"],["finalize","ทำให้เสร็จสมบูรณ์, สรุปขั้นสุดท้าย"],["accept","ตอบรับ"],["drop off","นำไปส่ง/คืน"],["cofounder","ผู้ร่วมก่อตั้ง"],["freight","การขนส่งสินค้า"],["specific","เฉพาะเจาะจง"]],"questions":[{"n":181,"question":"What is the purpose of the e-mail?","question_th":"จุดประสงค์ของอีเมลคืออะไร","type":"main","options":{"A":"To finalize a plan","B":"To accept an invitation","C":"To promote a new service","D":"To request feedback on a policy"},"options_th":{"A":"เพื่อสรุปแผนขั้นสุดท้าย","B":"เพื่อตอบรับคำเชิญ","C":"เพื่อโปรโมตบริการใหม่","D":"เพื่อขอความคิดเห็นเกี่ยวกับนโยบาย"},"answer":"A","category":"Topic/Purpose","category_th":"หัวข้อ/จุดประสงค์","explain_th":"ประโยคแรกขอบคุณข้อเสนอที่จะมารับสินค้าเองหรือจ่ายค่าขนส่งทางอากาศ/รถไฟเพิ่ม แล้วบอกว่าไม่จำเป็นเพราะจะนำไปส่งเองที่ Stranraer อีเมลจึงเขียนเพื่อสรุปแผนการจัดส่งสินค้า → (A)","evidence_quotes":["Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport.","Neither arrangement is necessary, as I am happy to deliver your items to you in Stranraer myself."],"part":7},{"n":182,"question":"Why will Mr. Boyle travel from Stranraer to Kirkcolm?","question_th":"ทำไมคุณ Boyle จะเดินทางจาก Stranraer ไป Kirkcolm","type":"detail","options":{"A":"To make a delivery","B":"To attend a meeting","C":"To drop off a rental car","D":"To visit with family members"},"options_th":{"A":"เพื่อส่งของ","B":"เพื่อเข้าประชุม","C":"เพื่อคืนรถเช่า","D":"เพื่อเยี่ยมสมาชิกครอบครัว"},"answer":"D","category":"Detail","category_th":"รายละเอียด","explain_th":"อีเมลบอกว่าจะส่งของให้คุณ Savard ที่ Stranraer ด้วยตัวเอง และบังเอิญว่าน้องสาวกับลูก ๆ อยู่ใกล้ ๆ ที่ Kirkcolm ก่อนไปหาพวกเขาจะขับรถเช่าไปส่งของที่บ้านเธอก่อน ดังนั้นการไป Kirkcolm คือไปเยี่ยมครอบครัว → (D)","evidence_quotes":["I am happy to deliver your items to you in Stranraer myself.","It so happens that my sister and her children live nearby in Kirkcolm.","Before seeing them, I will drive my rental car to your house and hand deliver the items to you."],"paraphrase":[["my sister and her children","family members"]],"part":7},{"n":183,"question":"What is indicated in the e-mail?","question_th":"อีเมลบอกเป็นนัยถึงอะไร","type":"inference","options":{"A":"Mr. Boyle’s sister is a cofounder of Ceoleire Classics.","B":"Mr. Boyle has been disappointed by air- and train-freight companies.","C":"Ms. Savard has purchased items from Mr. Boyle in the past.","D":"Ms. Savard prefers a specific brand of luggage."},"options_th":{"A":"น้องสาวของคุณ Boyle เป็นผู้ร่วมก่อตั้ง Ceoleire Classics","B":"คุณ Boyle เคยผิดหวังกับบริษัทขนส่งสินค้าทางอากาศและทางรถไฟ","C":"คุณ Savard เคยซื้อสินค้าจากคุณ Boyle มาก่อน","D":"คุณ Savard ชอบกระเป๋าเดินทางยี่ห้อหนึ่งเป็นพิเศษ"},"answer":"B","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"ย่อหน้าแรกเขาปฏิเสธข้อเสนอให้จ่ายค่าขนส่งทางอากาศหรือรถไฟ ย่อหน้าที่สองบอกว่าเห็นความเสียหายจากพนักงานขนสัมภาระที่ไม่ใส่ใจมามาก และนโยบายคือส่งเองหรือใช้บริการขนส่งทางบก/ทางทะเลที่ไว้ใจ จึงอนุมานได้ว่าเขาผิดหวังกับการขนส่งทางอากาศและรถไฟ → (B)","evidence_quotes":["Thank you for your kind offer to either pick up your online order from my shop or to pay extra for air or train transport.","Over the years, I’ve seen too much damage done by inattentive baggage handlers.","My policy is to deliver items personally whenever feasible or hire a ground- or sea-based courier service I trust."],"part":7},{"n":184,"question":"What is most likely true about Ms. Savard?","question_th":"ข้อใดน่าจะเป็นจริงเกี่ยวกับคุณ Savard","type":"cross","options":{"A":"She often travels for her job.","B":"She paid extra to have items hand delivered.","C":"She recently purchased musical instruments.","D":"She will meet Mr. Boyle at the rental car office."},"options_th":{"A":"เธอเดินทางไปทำงานบ่อย","B":"เธอจ่ายเงินเพิ่มเพื่อให้ส่งของถึงมือ","C":"เธอเพิ่งซื้อเครื่องดนตรี","D":"เธอจะพบคุณ Boyle ที่สำนักงานรถเช่า"},"answer":"C","category":"Cross-reference","category_th":"เชื่อมโยงหลายข้อความ","explain_th":"อีเมลบอกว่าคุณ Savard สั่งสินค้าออนไลน์และคุณ Boyle จะนำไปส่งเองที่ Stranraer ส่วนตั๋วเรือมีชื่อผู้โดยสาร Conor Boyle และสัมภาระมีกล่องเครื่องดนตรี 2 กล่อง (แมนโดลิน 1, กีตาร์ 1) จึงรู้ว่าสิ่งที่เขานำไปส่งคือเครื่องดนตรี → (C)","evidence_quotes":["Thank you for your kind offer to either pick up your online order from my shop","I am happy to deliver your items to you in Stranraer myself.","Passenger Name: | Conor Boyle","2 instrument cases (1 mandolin, 1 guitar)"],"part":7},{"n":185,"question":"How is Mr. Boyle traveling to Cairnryan on June 5 ?","question_th":"คุณ Boyle จะเดินทางไป Cairnryan ในวันที่ 5 มิถุนายนด้วยวิธีใด","type":"detail","options":{"A":"By car","B":"By train","C":"By boat","D":"By plane"},"options_th":{"A":"รถยนต์","B":"รถไฟ","C":"เรือ","D":"เครื่องบิน"},"answer":"C","category":"Detail","category_th":"รายละเอียด","explain_th":"ตั๋วมีหัวว่า Northern Ireland Ferry Service ชื่อผู้โดยสาร Conor Boyle และเทียบท่าที่ Cairnryan วันศุกร์ที่ 5 มิ.ย. 15:20 จึงรู้ว่าเขาจะไปด้วยเรือ → (C)","evidence_quotes":["Northern Ireland Ferry Service","Passenger Name: | Conor Boyle","Docking at Cairnryan: | Friday, 5 June, 3:20 PM"],"part":7}]},{"set":"186-190","part":7,"type":"advertisement + online forum posting + outline","passages":[{"label":"advertisement","text":"Train to Achieve (TTA)—Our classes prepare you to succeed!\n\nProfiled in the latest Business Directions Nigeria newsletter, Train to Achieve (TTA) is one of the most innovative training providers in West Africa. By offering our classes entirely in online format, we bring the classroom to your home. All classes include individualized instruction and are taught by recognized professionals in their respective fields. Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé. For a complete list of class fees and schedules, visit our Web site at www.traintoachieve.org.ng. The following are some of our most popular classes.\n\nIntroduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan, the class equips you with the know-how to promote your business online.\n\nBecome a Successful Freelance Writer (TTA3283): Business writer Brenda Akande gives you expert guidance on how to hone your writing skills and sell your writing services.\n\nStarting an Internet Radio Station (TTA7629): Online radio host Natalie Kabiru shows you how to appeal to your target market and gives practical tips for setting up your broadcast service.\n\nBasics of Graphic Design (TTA7633): Veteran graphic designer Doug Umaru helps you acquire the basic skills needed to start a graphic design business.","text_th":"Train to Achieve (TTA) — คอร์สของเราเตรียมคุณให้พร้อมสู่ความสำเร็จ!\n\nTrain to Achieve (TTA) ซึ่งได้รับการแนะนำในจดหมายข่าว Business Directions Nigeria ฉบับล่าสุด เป็นหนึ่งในผู้ให้บริการฝึกอบรมที่มีนวัตกรรมมากที่สุดในแอฟริกาตะวันตก ด้วยการเปิดสอนทุกคอร์สทางออนไลน์ทั้งหมด เราจึงนำห้องเรียนมาถึงบ้านคุณ ทุกคอร์สมีการสอนแบบรายบุคคล และสอนโดยมืออาชีพที่ได้รับการยอมรับในสาขาของตน เมื่อเรียนจบคอร์สสำเร็จ คุณจะได้รับประกาศนียบัตรการฝึกอบรมอย่างเป็นทางการ ซึ่งเป็นสิ่งที่เพิ่มคุณค่าให้เรซูเมของคุณ ดูรายการค่าเรียนและตารางเรียนทั้งหมดได้ที่เว็บไซต์ www.traintoachieve.org.ng ต่อไปนี้คือคอร์สยอดนิยมบางส่วนของเรา\n\nIntroduction to Social Media Marketing (TTA1504): สอนโดย Marcus Akpan ที่ปรึกษาด้านการตลาด คอร์สนี้ให้ความรู้วิธีโปรโมตธุรกิจของคุณทางออนไลน์\n\nBecome a Successful Freelance Writer (TTA3283): Brenda Akande นักเขียนด้านธุรกิจ ให้คำแนะนำระดับผู้เชี่ยวชาญเรื่องการฝึกฝนทักษะการเขียนและการขายบริการงานเขียน\n\nStarting an Internet Radio Station (TTA7629): Natalie Kabiru ผู้จัดรายการวิทยุออนไลน์ สอนวิธีดึงดูดกลุ่มเป้าหมาย และให้เคล็ดลับที่ใช้ได้จริงในการตั้งสถานีกระจายเสียง\n\nBasics of Graphic Design (TTA7633): Doug Umaru นักออกแบบกราฟิกผู้มากประสบการณ์ ช่วยให้คุณได้ทักษะพื้นฐานที่จำเป็นในการเริ่มธุรกิจออกแบบกราฟิก","image":"img/rc_t01_186-190_1.png"},{"label":"online forum posting","text":"Discussion forum for students enrolled in Train to Achieve Class TTA1504\n\nPosted on: 21 May, 9:41 A.M. | Posted by: Joseph Egbe | Subject: Presentations\n\nViewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January’s poster design class. I look forward to sharing our learning experiences again for this class. Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business. I own a food truck from which I sell baked goods, and when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods. It was helpful advice.","text_th":"กระดานสนทนาสำหรับผู้เรียนที่ลงทะเบียนคอร์ส TTA1504 ของ Train to Achieve\n\nโพสต์เมื่อ: 21 พฤษภาคม 9:41 น. | โพสต์โดย: Joseph Egbe | หัวข้อ: การนำเสนอ\n\nพอดูรายชื่อผู้เรียนที่ลงทะเบียนคอร์สนี้ ผมนึกขึ้นได้ว่าเคยคุยกับบางคนในกระดานสนทนาของคอร์สออกแบบโปสเตอร์เมื่อเดือนมกราคม ผมตั้งตารอที่จะได้แบ่งปันประสบการณ์การเรียนกันอีกครั้งในคอร์สนี้ เมื่อวานผมเป็นผู้เรียนคนที่สองที่ได้ประชุมทางวิดีโอแบบตัวต่อตัวกับคุณ Akpan เกี่ยวกับธุรกิจของผม ผมมีรถฟู้ดทรักขายขนมอบ และเมื่อผมแสดงโครงร่างเว็บไซต์ให้คุณ Akpan ดู เขาแนะนำให้เพิ่มส่วนที่มีภาพสวยสดของขนมอบทุกชนิด เป็นคำแนะนำที่มีประโยชน์มาก","image":"img/rc_t01_186-190_2.png"},{"label":"outline","text":"Egbe’s Bakery—Unique baked-in flavours in every bite!\n\n• Section 1: Explore our menu and price list\n• Section 2: Browse photos of our delicious treats\n• Section 3: Learn about our catering services\n• Section 4: View lists of ingredients","text_th":"Egbe’s Bakery — รสชาติอบเฉพาะตัวในทุกคำ!\n\n• ส่วนที่ 1: สำรวจเมนูและรายการราคา\n• ส่วนที่ 2: ดูรูปขนมแสนอร่อยของเรา\n• ส่วนที่ 3: เรียนรู้เกี่ยวกับบริการจัดเลี้ยงของเรา\n• ส่วนที่ 4: ดูรายการส่วนผสม","image":"img/rc_t01_186-190_3.png"}],"vocab":[["profile","แนะนำ, นำเสนอประวัติ"],["latest","ล่าสุด"],["innovative","มีนวัตกรรม"],["entirely","ทั้งหมด"],["individualized","เฉพาะบุคคล"],["instruction","การสอน"],["recognized","ได้รับการยอมรับ"],["respective","ของแต่ละคน"],["field","สาขา"],["completion","การจบ, การเสร็จสิ้น"],["official","อย่างเป็นทางการ"],["certificate","ประกาศนียบัตร"],["valuable","มีคุณค่า"],["addition","สิ่งที่เพิ่มเข้ามา"],["equip","ให้ (ความรู้/ทักษะ)"],["promote","โปรโมต"],["expert","ระดับผู้เชี่ยวชาญ"],["guidance","คำแนะนำ"],["hone","ฝึกฝนให้เก่งขึ้น"],["host","ผู้จัดรายการ"],["appeal","ดึงดูด"],["practical","ใช้ได้จริง"],["broadcast","การกระจายเสียง"],["veteran","ผู้มากประสบการณ์"],["acquire","ได้มา"],["enroll","ลงทะเบียนเรียน"],["individual","ตัวต่อตัว, รายบุคคล"],["outline","โครงร่าง"],["vivid","สดใส, ชัดเจน"],["flavour","รสชาติ"],["bite","คำ (อาหาร)"],["explore","สำรวจ"],["browse","ดูผ่าน ๆ"],["treat","ขนม, ของกินเล่น"],["catering","การจัดเลี้ยง"],["ingredient","ส่วนผสม"],["found","ก่อตั้ง"],["facility","สิ่งอำนวยความสะดวก, สถานที่"],["follow-up","ต่อเนื่อง"],["job posting","ประกาศรับสมัครงาน"],["certification","การรับรอง"],["previously","ก่อนหน้านี้"]],"questions":[{"n":186,"question":"What is indicated about TTA?","question_th":"ข้อใดกล่าวถึง TTA ได้ถูกต้อง","type":"not-true","options":{"A":"It was founded by a graphic designer.","B":"It publishes its own online newsletter.","C":"It offers classes led by industry professionals.","D":"It has classroom facilities in cities across West Africa."},"options_th":{"A":"ก่อตั้งโดยนักออกแบบกราฟิก","B":"จัดพิมพ์จดหมายข่าวออนไลน์ของตัวเอง","C":"มีคอร์สที่สอนโดยมืออาชีพในวงการ","D":"มีห้องเรียนในหลายเมืองทั่วแอฟริกาตะวันตก"},"answer":"C","category":"Not/True","category_th":"Not/True (ข้อใดถูก/ไม่ถูก)","explain_th":"โฆษณาประโยคที่สามบอกว่าทุกคอร์สมีการสอนแบบรายบุคคลและสอนโดยมืออาชีพที่ได้รับการยอมรับในสาขาของตน → (C)","evidence_quotes":["All classes include individualized instruction and are taught by recognized professionals in their respective fields."],"part":7},{"n":187,"question":"According to the advertisement, what does TTA provide to students who finish a class?","question_th":"ตามโฆษณา TTA มอบอะไรให้ผู้เรียนที่เรียนจบคอร์ส","type":"detail","options":{"A":"A résumé-writing workshop","B":"A discount on a follow-up class","C":"A list of current job postings","D":"A certification document"},"options_th":{"A":"เวิร์กช็อปเขียนเรซูเม","B":"ส่วนลดสำหรับคอร์สต่อเนื่อง","C":"รายการประกาศรับสมัครงานปัจจุบัน","D":"เอกสารรับรอง (ประกาศนียบัตร)"},"answer":"D","category":"Detail","category_th":"รายละเอียด","explain_th":"โฆษณาประโยคที่สี่บอกว่าเมื่อเรียนจบคอร์สสำเร็จ จะได้รับประกาศนียบัตรการฝึกอบรมอย่างเป็นทางการ → (D)","evidence_quotes":["Upon successful completion of a class, you will receive an official Certificate of Training, a valuable addition to any résumé."],"paraphrase":[["an official Certificate of Training","A certification document"]],"part":7},{"n":188,"question":"What is most likely true about Mr. Egbe?","question_th":"ข้อใดน่าจะเป็นจริงเกี่ยวกับคุณ Egbe","type":"inference","options":{"A":"He helped design a discussion forum.","B":"He has previously taken a TTA class.","C":"He develops videoconferencing software.","D":"He recently sold a bakery food truck."},"options_th":{"A":"เขาช่วยออกแบบกระดานสนทนา","B":"เขาเคยเรียนคอร์สของ TTA มาก่อน","C":"เขาพัฒนาซอฟต์แวร์ประชุมทางวิดีโอ","D":"เขาเพิ่งขายรถฟู้ดทรักขนมอบไป"},"answer":"B","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"ประโยคแรกของโพสต์บอกว่าพอดูรายชื่อผู้เรียนก็นึกได้ว่าเคยคุยกับบางคนในกระดานของคอร์สออกแบบโปสเตอร์เดือนมกราคม และตั้งตารอแบ่งปันประสบการณ์เรียนอีกครั้ง แสดงว่าเขาเคยเรียนคอร์สของ TTA มาก่อน → (B)","evidence_quotes":["Viewing the list of students enrolled in this class, I remembered chatting with some of you on the forum for January’s poster design class.","I look forward to sharing our learning experiences again for this class."],"part":7},{"n":189,"question":"What TTA class is Mr. Egbe enrolled in?","question_th":"คุณ Egbe ลงทะเบียนเรียนคอร์สใดของ TTA","type":"cross","options":{"A":"Introduction to Social Media Marketing","B":"Become a Successful Freelance Writer","C":"Starting an Internet Radio Station","D":"Basics of Graphic Design"},"options_th":{"A":"Introduction to Social Media Marketing (การตลาดโซเชียลมีเดียเบื้องต้น)","B":"Become a Successful Freelance Writer (การเป็นนักเขียนอิสระที่ประสบความสำเร็จ)","C":"Starting an Internet Radio Station (การเริ่มสถานีวิทยุอินเทอร์เน็ต)","D":"Basics of Graphic Design (พื้นฐานการออกแบบกราฟิก)"},"answer":"A","category":"Cross-reference","category_th":"เชื่อมโยงหลายข้อความ","explain_th":"หัวกระดานสนทนาระบุว่าเป็นของผู้เรียนคอร์ส TTA1504 และประโยคที่สามบอกว่าเขาได้ประชุมวิดีโอตัวต่อตัวกับคุณ Akpan ส่วนในโฆษณา คอร์ส TTA1504 คือ Introduction to Social Media Marketing สอนโดย Marcus Akpan → (A)","evidence_quotes":["Discussion forum for students enrolled in Train to Achieve Class TTA1504","Yesterday I was the second student to meet with Mr. Akpan for an individual videoconference about my business.","Introduction to Social Media Marketing (TTA1504): Taught by marketing consultant Marcus Akpan"],"part":7},{"n":190,"question":"What section did Mr. Egbe most likely add to the outline after speaking with Mr. Akpan?","question_th":"หลังจากคุยกับคุณ Akpan คุณ Egbe น่าจะเพิ่มส่วนใดในโครงร่าง","type":"cross","options":{"A":"Section 1","B":"Section 2","C":"Section 3","D":"Section 4"},"options_th":{"A":"ส่วนที่ 1","B":"ส่วนที่ 2","C":"ส่วนที่ 3","D":"ส่วนที่ 4"},"answer":"B","category":"Cross-reference","category_th":"เชื่อมโยงหลายข้อความ","explain_th":"โพสต์บอกว่าเมื่อเขาแสดงโครงร่างเว็บไซต์ คุณ Akpan แนะนำให้เพิ่มส่วนที่มีภาพขนมอบทุกชนิด และโครงร่างมี Section 2: ดูรูปขนมแสนอร่อย จึงเป็นส่วนที่เขาเพิ่มตามคำแนะนำ → (B)","evidence_quotes":["when I shared with Mr. Akpan the outline for my Web site, he suggested that I add a section with vivid images of all my baked goods","• Section 2: Browse photos of our delicious treats"],"part":7}]},{"set":"191-195","part":7,"type":"article + review + e-mail","passages":[{"label":"article","text":"Caribbean Flavours Abound\nBy Rebecca Roats\n\nNOTTINGHAM (1 August)—Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now. Managed by Keron Deslandes, the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square. The servers are always happy to help diners select from the variety of delights on the extensive menu, which includes curried goat, oxtail soup, and red snapper. The restaurant is most famous for its jerk chicken. Marinated for 24 hours prior to grilling and served with sides of stewed cabbage and coconut rice, the dish is a good deal at £12.\n\nIf you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music.","text_th":"รสชาติแคริบเบียนเต็มเปี่ยม\nโดย Rebecca Roats\n\nNOTTINGHAM (1 สิงหาคม) — Orange Bay Kitchen เสิร์ฟรสชาติจาเมกาในบรรยากาศแคริบเบียนแบบสบาย ๆ มาได้หกเดือนแล้ว ร้านอาหารขนาด 150 ที่นั่งซึ่งบริหารโดย Keron Deslandes แห่งนี้ เปรียบเสมือนอัญมณีหอมกรุ่นท่ามกลางร้านค้าและร้านอาหารที่คึกคักใน Wester Square พนักงานเสิร์ฟยินดีช่วยลูกค้าเลือกอาหารอร่อยหลากหลายจากเมนูมากมาย ซึ่งรวมถึงแกงกะหรี่แพะ ซุปหางวัว และปลากะพงแดง ร้านนี้มีชื่อเสียงที่สุดเรื่องไก่เจิร์ก (jerk chicken) ซึ่งหมักไว้ 24 ชั่วโมงก่อนย่าง และเสิร์ฟพร้อมเครื่องเคียงกะหล่ำปลีตุ๋นและข้าวมะพร้าว เป็นเมนูที่คุ้มค่าในราคา 12 ปอนด์\n\nหากแวะมาคืนวันศุกร์ใดก็ได้ระหว่าง 19:00–23:00 น. คุณจะได้เพลิดเพลินกับดนตรีเร็กเกสด"},{"label":"review","text":"https://www.dinerreviews.co.uk/orangebaykitchen\n\nPosted on 22 August by Tamika Peterkin, tpeterkin@sunmail.co.uk\n\nOrange Bay Kitchen: 2/5 Stars\n\nAfter reading a glowing article about Orange Bay Kitchen by Rebecca Roats, I was eager to give this place a try. My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner. Unfortunately, the band’s performance that night had been cancelled. Undeterred, we stayed and both ordered the jerk chicken. While the chicken’s smoky flavour was outstanding, the stewed cabbage was lacking in flavour. Also, the portion size was smaller than we had anticipated, so we ordered another appetiser to avoid going home hungry. The head chef came out to apologise and was extremely nice, but we will probably not go back anytime soon.","text_th":"https://www.dinerreviews.co.uk/orangebaykitchen\n\nโพสต์เมื่อ 22 สิงหาคม โดย Tamika Peterkin, tpeterkin@sunmail.co.uk\n\nOrange Bay Kitchen: 2/5 ดาว\n\nหลังจากอ่านบทความที่ชื่นชม Orange Bay Kitchen อย่างมากของ Rebecca Roats ฉันก็อยากไปลองมาก ฉันกับสามีไปถึงที่นั่นตอนหนึ่งทุ่มเมื่อวานนี้ ตั้งใจจะฟังดนตรีสดระหว่างทานมื้อค่ำ แต่น่าเสียดายที่การแสดงของวงดนตรีคืนนั้นถูกยกเลิก เราไม่ย่อท้อ อยู่ต่อและสั่งไก่เจิร์กกันทั้งคู่ แม้รสรมควันของไก่จะยอดเยี่ยม แต่กะหล่ำปลีตุ๋นกลับจืดชืด นอกจากนี้ปริมาณยังน้อยกว่าที่คาดไว้ เราจึงสั่งอาหารเรียกน้ำย่อยเพิ่มอีกจานเพื่อไม่ให้กลับบ้านไปหิว หัวหน้าเชฟออกมาขอโทษและเป็นมิตรมาก แต่เราคงไม่กลับไปอีกในเร็ว ๆ นี้","image":"img/rc_t01_191-195_2.png"},{"label":"e-mail","text":"To: tpeterkin@sunmail.co.uk\nFrom: vsmith@orangebaykitchen.co.uk\nDate: 24 August\nSubject: Your review\nAttachment: 0258\n\nDear Ms. Peterkin,\n\nThank you for visiting Orange Bay Kitchen and leaving a review. Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening. Please accept the attached £20 gift certificate; I do hope that you will give us another try.\n\nDuring your visit, our band had an equipment malfunction, which is what led to the last-minute cancellation. However, the band will be back performing weekly beginning in September. Also, I want you to know that Head Chef Adio Brown has changed the spices he uses in the stewed cabbage. I am sure you will find them delightful.\n\nSincerely,\n\nVea Smith, Owner\nOrange Bay Kitchen","text_th":"ถึง: tpeterkin@sunmail.co.uk\nจาก: vsmith@orangebaykitchen.co.uk\nวันที่: 24 สิงหาคม\nเรื่อง: รีวิวของคุณ\nไฟล์แนบ: 0258\n\nเรียน คุณ Peterkin\n\nขอบคุณที่มาใช้บริการ Orange Bay Kitchen และเขียนรีวิว Keron Deslandes ผู้จัดการของเราเล่ารายละเอียดเกี่ยวกับการมาของคุณ และการที่เราไม่สามารถทำได้ตามที่คุณคาดหวังในเย็นวันนั้นให้ดิฉันฟัง โปรดรับบัตรกำนัลมูลค่า 20 ปอนด์ที่แนบมา ดิฉันหวังเป็นอย่างยิ่งว่าคุณจะให้โอกาสเราอีกครั้ง\n\nระหว่างที่คุณมา อุปกรณ์ของวงดนตรีเกิดขัดข้อง จึงต้องยกเลิกการแสดงกะทันหัน อย่างไรก็ตาม วงดนตรีจะกลับมาแสดงทุกสัปดาห์ตั้งแต่เดือนกันยายน นอกจากนี้ดิฉันอยากให้คุณทราบว่าหัวหน้าเชฟ Adio Brown ได้เปลี่ยนเครื่องเทศที่ใช้ในกะหล่ำปลีตุ๋นแล้ว ดิฉันมั่นใจว่าคุณจะชอบ\n\nขอแสดงความนับถือ\n\nVea Smith เจ้าของร้าน\nOrange Bay Kitchen"}],"vocab":[["flavour","รสชาติ"],["abound","มีมากมาย"],["infusion","การผสมผสานใส่เข้าไป"],["laid-back","สบาย ๆ"],["atmosphere","บรรยากาศ"],["aromatic","หอม"],["jewel","อัญมณี"],["amid","ท่ามกลาง"],["bustling","คึกคัก"],["eatery","ร้านอาหาร"],["diner","ลูกค้าร้านอาหาร"],["delight","สิ่งที่น่ายินดี, ของอร่อย"],["extensive","กว้างขวาง, มีมาก"],["curried","ปรุงแบบแกงกะหรี่"],["oxtail","หางวัว"],["red snapper","ปลากะพงแดง"],["jerk","(อาหาร) หมักเครื่องเทศแล้วย่างแบบจาเมกา"],["marinate","หมัก"],["stewed","ตุ๋น"],["deal","ราคาคุ้มค่า"],["glowing","ชื่นชมอย่างมาก"],["be eager to","อยากจะ…มาก"],["undeterred","ไม่ย่อท้อ"],["smoky","มีกลิ่นรมควัน"],["outstanding","ยอดเยี่ยม"],["portion","ปริมาณต่อจาน"],["anticipate","คาดการณ์"],["live up to","ทำได้ตาม (ความคาดหวัง)"],["expectation","ความคาดหวัง"],["accept","รับ"],["gift certificate","บัตรกำนัล"],["malfunction","การทำงานผิดปกติ"],["last-minute","กะทันหัน, นาทีสุดท้าย"],["cancellation","การยกเลิก"],["spice","เครื่องเทศ"],["delightful","น่าพอใจ, อร่อย"],["apology","คำขอโทษ"]],"questions":[{"n":191,"question":"What does the article mention about Orange Bay Kitchen?","question_th":"บทความกล่าวถึงอะไรเกี่ยวกับ Orange Bay Kitchen","type":"not-true","options":{"A":"It is currently hiring servers.","B":"It is located on a quiet street.","C":"It has another location in Jamaica.","D":"It opened six months ago."},"options_th":{"A":"กำลังรับสมัครพนักงานเสิร์ฟ","B":"ตั้งอยู่บนถนนที่เงียบสงบ","C":"มีอีกสาขาหนึ่งที่จาเมกา","D":"เปิดมาได้หกเดือนแล้ว"},"answer":"D","category":"Not/True","category_th":"Not/True (ข้อใดถูก/ไม่ถูก)","explain_th":"ประโยคแรกของบทความบอกว่า Orange Bay Kitchen เสิร์ฟรสชาติจาเมกามาได้หกเดือนแล้ว แสดงว่าเปิดเมื่อหกเดือนก่อน → (D)  ประโยคที่สองบอกว่าตั้งอยู่ท่ามกลางร้านค้าที่คึกคัก ตัด (B) ส่วน (A)(C) ไม่ได้กล่าวถึง","evidence_quotes":["Orange Bay Kitchen has been serving up an infusion of Jamaican flavours in a laid-back Caribbean atmosphere for six months now.","the 150-seat restaurant is an aromatic jewel amid the bustling shops and eateries in Wester Square"],"part":7},{"n":192,"question":"According to the article, what is the most popular menu item at Orange Bay Kitchen?","question_th":"ตามบทความ เมนูที่ได้รับความนิยมที่สุดของ Orange Bay Kitchen คืออะไร","type":"detail","options":{"A":"Red snapper","B":"Oxtail soup","C":"Jerk chicken","D":"Curried goat"},"options_th":{"A":"ปลากะพงแดง","B":"ซุปหางวัว","C":"ไก่เจิร์ก","D":"แกงกะหรี่แพะ"},"answer":"C","category":"Detail","category_th":"รายละเอียด","explain_th":"ประโยคที่สี่ของบทความบอกว่าร้านนี้มีชื่อเสียงที่สุดเรื่องไก่เจิร์ก → (C)","evidence_quotes":["The restaurant is most famous for its jerk chicken."],"part":7},{"n":193,"question":"What is suggested about Ms. Peterkin’s visit to Orange Bay Kitchen?","question_th":"ข้อใดบอกเป็นนัยเกี่ยวกับการไป Orange Bay Kitchen ของคุณ Peterkin","type":"cross","options":{"A":"She was there on a Friday.","B":"She dined alone.","C":"She requested extra rice.","D":"She ordered dessert."},"options_th":{"A":"เธอไปที่นั่นในวันศุกร์","B":"เธอไปทานคนเดียว","C":"เธอขอข้าวเพิ่ม","D":"เธอสั่งของหวาน"},"answer":"A","category":"Cross-reference","category_th":"เชื่อมโยงหลายข้อความ","explain_th":"รีวิวบอกว่าเธอกับสามีไปถึงตอนหนึ่งทุ่มเมื่อวาน ตั้งใจจะฟังดนตรีสดระหว่างมื้อค่ำ และบทความประโยคสุดท้ายบอกว่าทุกคืนวันศุกร์ 19:00–23:00 มีดนตรีเร็กเกสด จึงรู้ว่าเธอไปในคืนวันศุกร์ที่ควรมีการแสดง → (A)","evidence_quotes":["My husband and I arrived there at 7 P.M. yesterday, keen to enjoy live music with our dinner.","If you stop in on any Friday night between 7 and 11 P.M., you will enjoy live reggae music."],"part":7},{"n":194,"question":"What is a purpose of the e-mail?","question_th":"จุดประสงค์หนึ่งของอีเมลคืออะไร","type":"main","options":{"A":"To answer a question","B":"To offer an apology","C":"To ask for feedback","D":"To confirm a reservation"},"options_th":{"A":"เพื่อตอบคำถาม","B":"เพื่อขอโทษ","C":"เพื่อขอความคิดเห็น","D":"เพื่อยืนยันการจอง"},"answer":"B","category":"Topic/Purpose","category_th":"หัวข้อ/จุดประสงค์","explain_th":"ประโยคที่สองของอีเมลบอกว่าผู้จัดการเล่าเรื่องการมาของเธอและการที่ร้านทำได้ไม่ตามความคาดหวัง แล้วขอให้รับบัตรกำนัลที่แนบมาและให้โอกาสอีกครั้ง จึงเป็นอีเมลขอโทษลูกค้าที่ผิดหวัง → (B)","evidence_quotes":["Our manager, Keron Deslandes, told me more about your visit and our failure to live up to your expectations that evening.","Please accept the attached £20 gift certificate; I do hope that you will give us another try."],"part":7},{"n":195,"question":"Whom did Ms. Peterkin meet at Orange Bay Kitchen?","question_th":"คุณ Peterkin ได้พบใครที่ Orange Bay Kitchen","type":"cross","options":{"A":"Ms. Roats","B":"Mr. Deslandes","C":"Mr. Brown","D":"Ms. Smith"},"options_th":{"A":"คุณ Roats","B":"คุณ Deslandes","C":"คุณ Brown","D":"คุณ Smith"},"answer":"C","category":"Cross-reference","category_th":"เชื่อมโยงหลายข้อความ","explain_th":"ประโยคสุดท้ายของรีวิวบอกว่าหัวหน้าเชฟออกมาขอโทษและเป็นมิตรมาก และอีเมลย่อหน้าที่สองระบุว่าหัวหน้าเชฟคือ Adio Brown จึงรู้ว่าเธอได้พบคุณ Brown → (C)","evidence_quotes":["The head chef came out to apologise and was extremely nice","Head Chef Adio Brown has changed the spices he uses in the stewed cabbage."],"part":7}]},{"set":"196-200","part":7,"type":"invoice + notice + e-mail","passages":[{"label":"invoice","text":"Orbys Distributors\n\nClient: Green Canyon | Date: June 10\nAccount: 4352-0\n\nItem | Price\nGarden soil, 33 cubic meters | $1,170.00\nCrushed gravel, 30 metric tons | 1,710.00\nDecorative stone, 20 metric tons | 1,140.00\n70 paving stones, .6 x .6 meters | 630.00\nSubtotal | 4,650.00\n\nDiscount (10%) | 465.00\nDelivery charge | 350.00\nGrand Total | 4,535.00\n\nPlease see the enclosed notice outlining important changes to your billing.","text_th":"Orbys Distributors\n\nลูกค้า: Green Canyon | วันที่: 10 มิถุนายน\nบัญชี: 4352-0\n\nรายการ | ราคา\nดินสำหรับสวน 33 ลูกบาศก์เมตร | 1,170.00 ดอลลาร์\nกรวดบด 30 เมตริกตัน | 1,710.00\nหินตกแต่ง 20 เมตริกตัน | 1,140.00\nแผ่นหินปูทาง 70 แผ่น ขนาด 0.6 x 0.6 เมตร | 630.00\nยอดรวมย่อย | 4,650.00\n\nส่วนลด (10%) | 465.00\nค่าจัดส่ง | 350.00\nยอดรวมทั้งสิ้น | 4,535.00\n\nโปรดดูประกาศที่แนบมาซึ่งสรุปการเปลี่ยนแปลงสำคัญเกี่ยวกับการเรียกเก็บเงินของท่าน","image":"img/rc_t01_196-200_1.png"},{"label":"notice","text":"Orbys Distributors\n\nTo our valued customers:\nOur current invoicing system has been in use since Orbys Distributors was founded over twenty years ago. As a much-needed upgrade, we are switching to electronic invoicing. Starting August 1, invoices will be generated automatically each month and will be sent to the e-mail address associated with your company’s account.\n\nRest assured that our long-standing incentives remain in place:\n\n• A 10% discount for orders of more than $4,000\n• A 20% discount for charitable organizations\n• Free deliveries to locations within 5 miles of one of our supply centers\n• Free samples for members of our Frequent Buyer Club\n\nMore information about our transition to electronic invoicing is available on our Web site. Thank you for your support. Orbys Distributors appreciates your business.","text_th":"Orbys Distributors\n\nเรียน ลูกค้าผู้มีอุปการคุณ\nระบบออกใบแจ้งหนี้ปัจจุบันของเราใช้มาตั้งแต่ Orbys Distributors ก่อตั้งเมื่อกว่ายี่สิบปีก่อน เพื่อเป็นการปรับปรุงที่จำเป็นอย่างยิ่ง เราจะเปลี่ยนไปใช้ใบแจ้งหนี้อิเล็กทรอนิกส์ ตั้งแต่วันที่ 1 สิงหาคม ใบแจ้งหนี้จะถูกสร้างขึ้นโดยอัตโนมัติทุกเดือน และส่งไปยังอีเมลที่ผูกกับบัญชีบริษัทของท่าน\n\nโปรดมั่นใจว่าสิทธิประโยชน์ที่มีมาอย่างยาวนานของเรายังคงอยู่เช่นเดิม:\n\n• ส่วนลด 10% สำหรับคำสั่งซื้อมากกว่า 4,000 ดอลลาร์\n• ส่วนลด 20% สำหรับองค์กรการกุศล\n• จัดส่งฟรีสำหรับสถานที่ในระยะ 5 ไมล์จากศูนย์จัดส่งสินค้าแห่งใดแห่งหนึ่งของเรา\n• ตัวอย่างสินค้าฟรีสำหรับสมาชิก Frequent Buyer Club\n\nดูข้อมูลเพิ่มเติมเกี่ยวกับการเปลี่ยนไปใช้ใบแจ้งหนี้อิเล็กทรอนิกส์ได้ที่เว็บไซต์ของเรา ขอบคุณสำหรับการสนับสนุน Orbys Distributors ขอบคุณที่ใช้บริการ","image":"img/rc_t01_196-200_2.png"},{"label":"e-mail","text":"To: Mary Peterson, Billing Department\nFrom: Tanvir Singh, Account Manager\nDate: September 12\nSubject: Account 1012-4\n\nHello Mary,\n\nI received a query today from William Tesoriero at Tesoriero Remodeling. His monthly invoice for August never arrived.\n\nAs you know, Mr. Tesoriero was one of our very first customers. Since we first opened for business, he has made purchases from us on a regular basis. He is also a member of the Frequent Buyer Club. This is a customer we absolutely do not want to lose. I explained to him that the rollout of our electronic invoicing system did not go as smoothly as we had hoped and promised that this would not happen again.\n\nI would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero.\n\nTanvir","text_th":"ถึง: Mary Peterson ฝ่ายเรียกเก็บเงิน\nจาก: Tanvir Singh ผู้จัดการฝ่ายลูกค้าสัมพันธ์\nวันที่: 12 กันยายน\nเรื่อง: บัญชี 1012-4\n\nสวัสดี Mary\n\nวันนี้ผมได้รับคำสอบถามจาก William Tesoriero แห่ง Tesoriero Remodeling ว่าใบแจ้งหนี้ประจำเดือนสิงหาคมของเขาไม่เคยมาถึงเลย\n\nอย่างที่คุณทราบ คุณ Tesoriero เป็นหนึ่งในลูกค้ากลุ่มแรกสุดของเรา ตั้งแต่เราเริ่มเปิดกิจการ เขาก็ซื้อสินค้าจากเราเป็นประจำ เขายังเป็นสมาชิก Frequent Buyer Club ด้วย เป็นลูกค้าที่เราไม่อยากเสียไปเด็ดขาด ผมอธิบายให้เขาฟังว่าการเริ่มใช้ระบบใบแจ้งหนี้อิเล็กทรอนิกส์ไม่ได้ราบรื่นอย่างที่เราหวัง และสัญญาว่าจะไม่เกิดเรื่องแบบนี้อีก\n\nผมจะขอบคุณมากถ้าคุณช่วยตรวจสอบปัญหานี้โดยด่วน และส่งใบแจ้งหนี้เดือนสิงหาคมให้คุณ Tesoriero\n\nTanvir"}],"vocab":[["distributor","ผู้จัดจำหน่าย"],["cubic meter","ลูกบาศก์เมตร"],["crushed","ที่ถูกบด"],["gravel","กรวด"],["metric ton","เมตริกตัน"],["decorative","สำหรับตกแต่ง"],["paving","การปูทาง"],["subtotal","ยอดรวมย่อย"],["enclosed","ที่แนบมา"],["outline","สรุปโดยย่อ"],["billing","การเรียกเก็บเงิน"],["valued","มีค่า, ที่ให้ความสำคัญ"],["invoicing","การออกใบแจ้งหนี้"],["found","ก่อตั้ง"],["switch","เปลี่ยน"],["invoice","ใบแจ้งหนี้"],["generate","สร้าง"],["automatically","โดยอัตโนมัติ"],["be associated with","เชื่อมโยงกับ"],["rest assured that","มั่นใจได้ว่า"],["long-standing","ที่มีมานาน"],["incentive","สิ่งจูงใจ, สิทธิประโยชน์"],["in place","มีผลใช้อยู่"],["charitable","เพื่อการกุศล"],["organization","องค์กร"],["supply","การจัดหาสินค้า"],["frequent","บ่อย, ประจำ"],["transition","การเปลี่ยนผ่าน"],["query","คำสอบถาม"],["on a regular basis","เป็นประจำ"],["rollout","การเปิดตัว/เริ่มใช้"],["smoothly","อย่างราบรื่น"],["investigate","ตรวจสอบ"],["landscaping","การจัดภูมิทัศน์"],["highway","ทางหลวง"],["belong to","เป็นสมาชิกของ"],["employment","การจ้างงาน"],["construction","การก่อสร้าง"],["machinery","เครื่องจักร"]],"questions":[{"n":196,"question":"What does the invoice suggest about Green Canyon?","question_th":"ใบแจ้งหนี้บอกเป็นนัยอะไรเกี่ยวกับ Green Canyon","type":"inference","options":{"A":"It does landscaping projects.","B":"It designs highways.","C":"It repairs old houses.","D":"It operates a farm."},"options_th":{"A":"ทำโครงการจัดภูมิทัศน์","B":"ออกแบบทางหลวง","C":"ซ่อมบ้านเก่า","D":"ดำเนินกิจการฟาร์ม"},"answer":"A","category":"Inference","category_th":"อนุมาน/สิ่งที่บอกเป็นนัย","explain_th":"รายการสินค้าในใบแจ้งหนี้มีดินสำหรับสวน กรวดบด หินตกแต่ง และแผ่นหินปูทาง แสดงว่า Green Canyon ซื้อวัสดุสำหรับจัดสวน จึงอนุมานได้ว่าทำงานจัดภูมิทัศน์ → (A)","evidence_quotes":["Garden soil, 33 cubic meters","Crushed gravel, 30 metric tons","Decorative stone, 20 metric tons"],"part":7},{"n":197,"question":"Why most likely did Green Canyon receive a discount on its order dated June 10 ?","question_th":"ทำไม Green Canyon จึงน่าจะได้รับส่วนลดสำหรับคำสั่งซื้อลงวันที่ 10 มิถุนายน","type":"cross","options":{"A":"It is a charitable organization.","B":"It belongs to the Frequent Buyer Club.","C":"It spent more than $4,000 on merchandise.","D":"It is located near an Orbys Distributors supply center."},"options_th":{"A":"เป็นองค์กรการกุศล","B":"เป็นสมาชิก Frequent Buyer Club","C":"ซื้อสินค้ามากกว่า 4,000 ดอลลาร์","D":"ตั้งอยู่ใกล้ศูนย์จัดส่งสินค้าของ Orbys Distributors"},"answer":"C","category":"Cross-reference","category_th":"เชื่อมโยงหลายข้อความ","explain_th":"ประกาศระบุสิทธิประโยชน์ข้อแรกว่าลด 10% สำหรับคำสั่งซื้อมากกว่า 4,000 ดอลลาร์ และใบแจ้งหนี้ลงวันที่ 10 มิ.ย. มียอดรวมย่อย 4,650 ดอลลาร์ ได้ส่วนลด 10% = 465 ดอลลาร์ จึงได้ส่วนลดเพราะซื้อเกิน 4,000 ดอลลาร์ → (C)","evidence_quotes":["• A 10% discount for orders of more than $4,000","Subtotal | 4,650.00","Discount (10%) | 465.00"],"part":7},{"n":198,"question":"According to the notice, what is changing at Orbys Distributors?","question_th":"ตามประกาศ อะไรกำลังจะเปลี่ยนที่ Orbys Distributors","type":"detail","options":{"A":"Its e-mail address","B":"Its list of incentives","C":"Its invoicing system","D":"Its delivery schedule"},"options_th":{"A":"ที่อยู่อีเมล","B":"รายการสิทธิประโยชน์","C":"ระบบออกใบแจ้งหนี้","D":"ตารางการจัดส่ง"},"answer":"C","category":"Detail","category_th":"รายละเอียด","explain_th":"ประโยคแรกของประกาศบอกว่าระบบออกใบแจ้งหนี้ปัจจุบันใช้มาตั้งแต่ก่อตั้งกว่า 20 ปีก่อน และจะเปลี่ยนเป็นใบแจ้งหนี้อิเล็กทรอนิกส์เพื่อปรับปรุงที่จำเป็น → (C)","evidence_quotes":["Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago.","As a much-needed upgrade, we are switching to electronic invoicing."],"part":7},{"n":199,"question":"What is suggested about Mr. Tesoriero?","question_th":"ข้อใดบอกเป็นนัยเกี่ยวกับคุณ Tesoriero","type":"cross","options":{"A":"He asked to meet with Mr. Singh.","B":"He is interested in employment at Orbys Distributors.","C":"He recently placed an order for some construction machinery.","D":"He has been a customer of Orbys Distributors for about twenty years."},"options_th":{"A":"เขาขอพบคุณ Singh","B":"เขาสนใจทำงานที่ Orbys Distributors","C":"เขาเพิ่งสั่งซื้อเครื่องจักรก่อสร้าง","D":"เขาเป็นลูกค้าของ Orbys Distributors มาประมาณยี่สิบปี"},"answer":"D","category":"Cross-reference","category_th":"เชื่อมโยงหลายข้อความ","explain_th":"อีเมลบอกว่าคุณ Tesoriero เป็นหนึ่งในลูกค้ากลุ่มแรกสุดและซื้อเป็นประจำตั้งแต่บริษัทเปิดกิจการ ส่วนประกาศบอกว่าบริษัทก่อตั้งเมื่อกว่า 20 ปีก่อน จึงรู้ว่าเขาเป็นลูกค้ามาราว 20 ปี → (D)","evidence_quotes":["As you know, Mr. Tesoriero was one of our very first customers.","Since we first opened for business, he has made purchases from us on a regular basis.","Our current invoicing system has been in use since Orbys Distributors was founded over twenty years ago."],"part":7},{"n":200,"question":"What does Mr. Singh ask Ms. Peterson to do?","question_th":"คุณ Singh ขอให้คุณ Peterson ทำอะไร","type":"detail","options":{"A":"Make a bill payment","B":"Solve a problem","C":"Confirm an order","D":"Update an account number"},"options_th":{"A":"ชำระบิล","B":"แก้ไขปัญหา","C":"ยืนยันคำสั่งซื้อ","D":"อัปเดตหมายเลขบัญชี"},"answer":"B","category":"Detail","category_th":"รายละเอียด","explain_th":"ประโยคสุดท้ายของอีเมลขอให้ตรวจสอบปัญหาโดยด่วนและส่งใบแจ้งหนี้เดือนสิงหาคมให้คุณ Tesoriero คือขอให้แก้ปัญหาเรื่องใบแจ้งหนี้ทันที → (B)","evidence_quotes":["I would appreciate it if you could please investigate the problem without delay and send the invoice for August to Mr. Tesoriero."],"part":7}]}]}};
